DROP TABLE IF EXISTS `productos_proveedor`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `productos_proveedor` (
  `ad_productos_proveedor` int NOT NULL COMMENT 'Secuencia asociada seq_productos_proveedor',
  `fk_productos_ad_producto` int NOT NULL,
  `fk_proveedor_ad_proveedor` int NOT NULL,
  `ds_producto_proveedor` varchar(100) NOT NULL,
  `vl_cantidad_equivalente` decimal(12,4) NOT NULL DEFAULT '0.0000' COMMENT 'Hace referencia a cuantas unidades base de tu producto interno representa la presentación del proveedor',
  PRIMARY KEY (`ad_productos_proveedor`),
  UNIQUE KEY `uk_producto_proveedor` (`fk_productos_ad_producto`,`fk_proveedor_ad_proveedor`),
  UNIQUE KEY `ds_producto_proveedor_UNIQUE` (`ds_producto_proveedor`,`fk_proveedor_ad_proveedor`),
  KEY `fk_proveedor_prodprovee` (`fk_proveedor_ad_proveedor`),
  CONSTRAINT `fk_productos_prodprovee` FOREIGN KEY (`fk_productos_ad_producto`) REFERENCES `productos` (`ad_producto`),
  CONSTRAINT `fk_proveedor_prodprovee` FOREIGN KEY (`fk_proveedor_ad_proveedor`) REFERENCES `proveedor` (`ad_proveedor`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

