  `ds_identificacion` varchar(20) NOT NULL,
  `nm_digito_verificacion` int DEFAULT NULL,
  `ds_razon_social` varchar(80) NOT NULL,
  `ds_nombre_comercial` varchar(80) DEFAULT NULL,
  `ds_direccion` varchar(100) DEFAULT NULL,
  `ds_ciudad` varchar(45) DEFAULT NULL,
  `ds_correo_electronico` varchar(100) DEFAULT NULL,
  `ds_pagina_web` varchar(45) DEFAULT NULL,
  `ds_telefono` varchar(45) DEFAULT NULL,
  `cl_tipo_proveedor` varchar(2) DEFAULT 'AL' COMMENT 'Dominio asociado DOM_TIPO_PROVEEDOR',
  `cl_tipo_persona` varchar(2) NOT NULL DEFAULT 'JU' COMMENT 'Dominio asociado DOM_TIPO_PERSONA',
