  `nm_dias_pago` int NOT NULL DEFAULT '0',
  `ic_responsable_iva` varchar(2) NOT NULL DEFAULT 'NO' COMMENT 'Dominio asociado DOM_SI_NO',
  `ic_aplica_retencion` varchar(2) NOT NULL DEFAULT 'NO' COMMENT 'Dominio asociado DOM_SI_NO',
  `ic_aplica_IVA` varchar(2) NOT NULL DEFAULT 'NO' COMMENT 'Dominio asociado DOM_SI_NO',
  `ic_precio_con_iva` varchar(2) NOT NULL DEFAULT 'NO' COMMENT 'Dominio asociado DOM_SI_NO',
  `ic_aplica_ICA` varchar(2) NOT NULL DEFAULT 'NO' COMMENT 'Dominio asociado DOM_SI_NO',
  `ds_contacto` varchar(45) DEFAULT NULL,
  `dt_creacion` date NOT NULL DEFAULT (curdate()),
  `ic_registro_activo` varchar(1) NOT NULL DEFAULT 'Y',
  `nm_cuenta_puc` int NOT NULL COMMENT 'Cuenta contable asociada, tomada del PUC',
  PRIMARY KEY (`ad_proveedor`),
  CONSTRAINT `ck_provee_ic_registro_activo` CHECK ((`ic_registro_activo` in (_utf8mb4'Y',_utf8mb4'N'))),
  CONSTRAINT `ck_provee_tipo_identif` CHECK ((`cl_tipo_identificacion` in (_utf8mb4'NI',_utf8mb4'CC')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
