CREATE DEFINER=`root`@`localhost` FUNCTION `fn_convertir_a_cantidad_base`(
    p_ad_productos_proveedor INT,
    p_cantidad_proveedor DECIMAL(12,4)
) RETURNS decimal(14,4)
    DETERMINISTIC
BEGIN
    DECLARE v_equivalente DECIMAL(12,4);
    DECLARE v_cantidad_base DECIMAL(14,4);

    -- Obtener equivalencia
    SELECT vl_cantidad_equivalente
    INTO v_equivalente
    FROM productos_proveedor
    WHERE ad_productos_proveedor = p_ad_productos_proveedor;

    -- Validación mínima
    IF v_equivalente IS NULL OR v_equivalente <= 0 THEN
        RETURN 0;
    END IF;

    SET v_cantidad_base = p_cantidad_proveedor * v_equivalente;

    RETURN v_cantidad_base;
END ;;
DELIMITER ;
