CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_cerrar_factura_compra`(
    IN p_ad_factura INT,
    OUT p_mensaje VARCHAR(255)
)
proc: BEGIN
    DECLARE v_facturado DECIMAL(12,4) DEFAULT 0;
    DECLARE v_descuento DECIMAL(12,4) DEFAULT 0;
    DECLARE v_impuestos DECIMAL(12,4) DEFAULT 0;
    DECLARE v_retencion DECIMAL(12,4) DEFAULT 0;
    DECLARE v_total DECIMAL(12,4) DEFAULT 0;
    DECLARE v_estado VARCHAR(20);
    DECLARE v_existe INT DEFAULT 0;
    DECLARE v_error TEXT;
    DECLARE v_fk_orden INT;
    DECLARE v_fk_proveedor INT;

    /* ================= MANEJO DE ERRORES ================= */
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 v_error = MESSAGE_TEXT;
        ROLLBACK;
        SET p_mensaje = CONCAT('ERROR: ', v_error);
    END;

    /* ================= VALIDACIONES ================= */
    IF p_ad_factura IS NULL THEN
        SET p_mensaje = 'ERROR: ID de factura obligatorio';
        LEAVE proc;
    END IF;

    SELECT ds_estado_factura,
           vl_descuento,
           vl_retencion,
           vl_impuestos,
           fk_ordencom_ad_orden,
           fk_provee_ad_proveedor
    INTO v_estado,
         v_descuento,
         v_retencion,
         v_impuestos,
         v_fk_orden,
         v_fk_proveedor
    FROM factura_compra
    WHERE ad_factura = p_ad_factura;

    IF v_estado IS NULL THEN
        SET p_mensaje = 'ERROR: La factura no existe';
        LEAVE proc;
    END IF;

    IF v_estado <> 'RE' THEN
        SET p_mensaje = 'ERROR: La factura ya fue cerrada o no es editable';
        LEAVE proc;
    END IF;

    /* Validar detalle */
    SELECT COUNT(*)
    INTO v_existe
    FROM detalle_factura_compra
    WHERE fk_factura_ad_factura = p_ad_factura;

    IF v_existe = 0 THEN
        SET p_mensaje = 'ERROR: La factura no tiene detalle';
        LEAVE proc;
    END IF;

    START TRANSACTION;

    /* ================= CALCULAR BASE ================= */
    SELECT SUM(vl_subtotal)
    INTO v_facturado
    FROM detalle_factura_compra
    WHERE fk_factura_ad_factura = p_ad_factura;

    /* ================= IMPUESTOS ================= */
    IF v_impuestos = 0 THEN
        SELECT IFNULL(SUM(vl_impuesto),0)
        INTO v_impuestos
        FROM factura_compra_impuesto
        WHERE fk_factura_ad_factura = p_ad_factura;
    END IF;

    /* ================= VALIDACIONES FINANCIERAS ================= */
    IF v_facturado <= 0 THEN
        SET p_mensaje = 'ERROR: Valor facturado inválido';
        ROLLBACK;
        LEAVE proc;
    END IF;

    IF v_impuestos < 0 OR v_descuento < 0 OR v_retencion < 0 THEN
        SET p_mensaje = 'ERROR: Valores financieros inválidos';
        ROLLBACK;
        LEAVE proc;
    END IF;

    /* ================= TOTAL ================= */
    SET v_total = v_facturado - v_descuento + v_impuestos;

    IF v_total <= 0 THEN
        SET p_mensaje = 'ERROR: Total de factura inválido';
        ROLLBACK;
        LEAVE proc;
    END IF;

    /* ================= ACTUALIZAR FACTURA ================= */
    UPDATE factura_compra
    SET vl_facturado = v_facturado,
        vl_impuestos = v_impuestos,
        vl_total = v_total,
        ds_estado_factura = 'CE'
    WHERE ad_factura = p_ad_factura;

    /* ================= CERRAR ORDEN ================= */
    IF v_fk_orden IS NOT NULL THEN
        UPDATE ordenes_compra
        SET ds_estado = 'CO'
        WHERE ad_orden = v_fk_orden;
    END IF;

    COMMIT;

    SET p_mensaje = CONCAT(
        'Factura cerrada correctamente. ',
        'Base=', v_facturado,
        ' Impuestos=', v_impuestos,
        ' Total=', v_total
    );

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
