/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_crear_particion_mensual`()
BEGIN
    DECLARE v_fecha_nueva DATE;
    DECLARE v_nombre_particion VARCHAR(20);
    DECLARE v_limite_todays INT;
    
    -- 1. Calcular el primer día del mes subsiguiente
    SET v_fecha_nueva = DATE_ADD(LAST_DAY(DATE_ADD(NOW(), INTERVAL 1 MONTH)), INTERVAL 1 DAY);
    
    -- 2. Formatear el nombre de la partición (Ej: p_202607)
    SET v_nombre_particion = DATE_FORMAT(DATE_SUB(v_fecha_nueva, INTERVAL 1 MONTH), 'p_%Y%m');
    
    -- 3. Calcular el entero numérico TO_DAYS
    SET v_limite_todays = TO_DAYS(v_fecha_nueva);
    
    -- 4. Construir y ejecutar la sentencia dinámica
    SET @sql_comando = CONCAT(
        'ALTER TABLE consumo REORGANIZE PARTITION p_futuro INTO (',
        '  PARTITION ', v_nombre_particion, ' VALUES LESS THAN (', v_limite_todays, '), ',
        '  PARTITION p_futuro VALUES LESS THAN MAXVALUE',
        ')'
    );
    
    -- Ejecución real
     PREPARE stmt FROM @sql_comando;
     EXECUTE stmt;
     DEALLOCATE PREPARE stmt;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
