CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_generar_cotizacion_desde_pedido`(IN p_pedido_id INT,
    IN p_proveedor_id INT,
    IN p_grupo_id INT,
    IN p_subgrupo_id INT,
    OUT p_mensaje VARCHAR(255)
    )
proc: BEGIN
-- Variables
    DECLARE v_cotizacion_id INT;
    DECLARE v_sucursal_id INT;
    DECLARE v_done INT DEFAULT 0;
    DECLARE v_producto_id INT;
    DECLARE v_cantidad DECIMAL(12,4);
    DECLARE v_prodprov_id INT;
    DECLARE v_error TEXT;

    -- Cursor con filtro por grupo/subgrupo
    DECLARE cur_detalle CURSOR FOR
        SELECT dp.fk_product_ad_producto,
             dp.vl_cantidad
        FROM detalle_pedido dp,
             productos pr,
             subgrupo_producto sg
        WHERE dp.fk_pedido_ad_pedido = p_pedido_id
          AND dp.ic_registro_activo = 'S'
          AND dp.fk_product_ad_producto = pr.ad_producto
          AND sg.ad_subgrupo_producto = pr.fk_subgrupo_ad_subgrupo_producto
          AND sg.fk_grupo_ad_grupo_producto = p_grupo_id
          AND (
                p_subgrupo_id IS NULL 
                OR pr.fk_subgrupo_ad_subgrupo_producto = p_subgrupo_id
              );

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;

    -- Manejo de errores
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 v_error = MESSAGE_TEXT;
        ROLLBACK;
        SET p_mensaje = CONCAT('ERROR: ', v_error);
    END;

    START TRANSACTION;

    -- Validar pedido
    IF NOT EXISTS (
        SELECT 1 
        FROM pedido 
        WHERE ad_pedido = p_pedido_id
          AND ds_estado_pedido = 'abierto'
    ) THEN
        SET p_mensaje = 'ERROR: El pedido no existe o no está abierto';
        ROLLBACK;
        LEAVE proc;
    END IF;

    -- Obtener sucursal
    SELECT fk_sucursal_ad_sucursal
    INTO v_sucursal_id
    FROM pedido
    WHERE ad_pedido = p_pedido_id;

    -- Generar cotización
    SET v_cotizacion_id = fn_actualiza_secuencias('seq_cotizacion');

    INSERT INTO cotizacion (
        ad_cotizacion,
        fk_provee_ad_proveedor,
        fk_sucursal_ad_sucursal,
        dt_fecha_cotizacion,
        ds_estado,
        ic_activa
    )
    VALUES (
        v_cotizacion_id,
        p_proveedor_id,
        v_sucursal_id,
        CURDATE(),
        'borrador',
        'S'
    );

    -- Recorrer detalle
    OPEN cur_detalle;

    read_loop: LOOP
        FETCH cur_detalle INTO v_producto_id, v_cantidad;

        IF v_done = 1 THEN
            LEAVE read_loop;
        END IF;

        -- Buscar producto_proveedor
        SET v_prodprov_id = NULL;

        SELECT ad_productos_proveedor
        INTO v_prodprov_id
        FROM productos_proveedor
        WHERE fk_productos_ad_producto = v_producto_id
          AND fk_proveedor_ad_proveedor = p_proveedor_id
        LIMIT 1;

        -- Si no existe → crear
        IF v_prodprov_id IS NULL THEN

            SET v_prodprov_id = fn_actualiza_secuencias('seq_productos_proveedor');

            INSERT INTO productos_proveedor (
                ad_productos_proveedor,
                fk_productos_ad_producto,
                fk_proveedor_ad_proveedor,
                ds_producto_proveedor,
                vl_cantidad_equivalente
            )
            SELECT 
                v_prodprov_id,
                p.ad_producto,
                p_proveedor_id,
                p.nm_producto,
                1
            FROM productos p
            WHERE p.ad_producto = v_producto_id;

        END IF;

        -- Insertar detalle cotización (valores en 0)
        INSERT INTO detalle_cotizacion (
            ad_cotizacion_detalle,
            fk_cotizacion_ad_cotizacion,
            fk_prodprov_ad_produprov,
            vl_cantidad,
            vl_precio_unitario,
            vl_subtotal
        )
        VALUES (
            fn_actualiza_secuencias('seq_cotizacion_detalle'),
            v_cotizacion_id,
            v_prodprov_id,
            v_cantidad,
            0,
            0
        );

    END LOOP;

    CLOSE cur_detalle;

    SET p_mensaje = 'Cotización generada exitosamente';
    COMMIT;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_generar_ordenes_compra_desde_pedido` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_generar_ordenes_compra_desde_pedido`(
    IN p_ad_pedido INT,
    OUT p_mensaje VARCHAR(255)
)
proc: BEGIN
	DECLARE v_sucursal INT;
    DECLARE v_estado_pedido ENUM('abierto','cerrado');
    DECLARE v_proveedor INT;
    DECLARE v_total DECIMAL(12,4);
    DECLARE v_ad_orden INT;
    DECLARE fin INT DEFAULT 0;
    DECLARE v_error TEXT;
    DECLARE v_dt_fecha_entrega DATE;

    /* Cursor de proveedores */
    DECLARE cur_proveedores CURSOR FOR
        SELECT DISTINCT fk_proveedor_ad_proveedor
        FROM detalle_pedido
        WHERE fk_pedido_ad_pedido = p_ad_pedido
          AND ic_registro_activo = 'S'
          AND fk_proveedor_ad_proveedor IS NOT NULL;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET fin = 1;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 v_error = MESSAGE_TEXT;
        ROLLBACK;

        INSERT INTO log_errores (
            modulo, operacion, mensaje_error, datos_entrada
        ) VALUES (
            'sp_generar_ordenes_compra_desde_pedido',
            'GENERAR',
            v_error,
            CONCAT('pedido=', p_ad_pedido)
        );

        SET p_mensaje = CONCAT('ERROR: ', v_error);
    END;

    /* 1️. Validar pedido */
    SELECT fk_sucursal_ad_sucursal, ds_estado_pedido, dt_fecha_entrega
    INTO v_sucursal, v_estado_pedido, v_dt_fecha_entrega
    FROM pedido
    WHERE ad_pedido = p_ad_pedido;

    IF v_sucursal IS NULL THEN
        SET p_mensaje = 'ERROR: El pedido no existe';
        LEAVE proc;
    END IF;

    IF v_estado_pedido <> 'abierto' THEN
        SET p_mensaje = 'ERROR: El pedido ya está cerrado';
        LEAVE proc;
    END IF;

    START TRANSACTION;

    /* 2️. Recorrer proveedores */
    OPEN cur_proveedores;

    proveedores_loop: LOOP
        FETCH cur_proveedores INTO v_proveedor;
        IF fin = 1 THEN
            LEAVE proveedores_loop;
        END IF;

        /* Total por proveedor */
        SELECT SUM(vl_cantidad * vl_compra)
        INTO v_total
        FROM detalle_pedido
        WHERE fk_pedido_ad_pedido = p_ad_pedido
          AND fk_proveedor_ad_proveedor = v_proveedor
          AND ic_registro_activo = 'S';

        /* Crear orden */
        SET v_ad_orden = fn_actualiza_secuencias('seq_ordenes_compra');

        INSERT INTO ordenes_compra (
            ad_orden,
            fk_sucursal_ad_sucursal,
            fk_provee_ad_proveedor,
            dt_fecha_orden,
            ds_estado,
            vl_total,
            ds_metodo_pago,
            dt_fecha_entrega,
            observaciones
        ) VALUES (
            v_ad_orden,
            v_sucursal,
            v_proveedor,
            NOW(),
            'PE',
            v_total,
            'TR',
            v_dt_fecha_entrega,
            CONCAT('Generada desde pedido interno #', p_ad_pedido)
        );

        /* Detalle de la orden */
        INSERT INTO detalles_orden_compra (
            ad_detalle_ordencom,
            fk_ordencom_ad_orden,
            fk_prodprov_ad_produprov,
            vl_cantidad,
            vl_precio_unitario,
            vl_subtotal
        )
        SELECT
            fn_actualiza_secuencias('seq_detalles_orden_compra'),
            v_ad_orden,
            pp.ad_productos_proveedor,
            dp.vl_cantidad,
            dp.vl_compra,
            dp.vl_cantidad * dp.vl_compra
        FROM detalle_pedido dp, productos_proveedor pp
        WHERE dp.fk_pedido_ad_pedido = p_ad_pedido
          AND dp.fk_proveedor_ad_proveedor = v_proveedor
          AND dp.ic_registro_activo = 'S'
          AND dp.fk_proveedor_ad_proveedor = pp.fk_proveedor_ad_proveedor
          AND pp.fk_productos_ad_producto = dp.fk_product_ad_producto;

    END LOOP;

    CLOSE cur_proveedores;

    /* 3️. Cerrar pedido */
    UPDATE pedido
    SET ds_estado_pedido = 'cerrado'
    WHERE ad_pedido = p_ad_pedido;

    COMMIT;

    SET p_mensaje = CONCAT(
        'Órdenes de compra generadas correctamente desde el pedido ',
        p_ad_pedido
    );

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_gestionar_banco` */;
