/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_gestionar_detalle_factura_compra`(
    IN p_fk_factura_ad_factura INT,
    IN p_fk_product_ad_producto INT,
    IN p_fk_prodpro_ad_product_prove INT,
    IN p_vl_cantidad DECIMAL(12,4),
    IN p_vl_costo_unitario DECIMAL(12,4),
    OUT p_id_detalle_factura INT,
    OUT p_mensaje VARCHAR(255)
)
proc: BEGIN
    DECLARE v_error TEXT;
    DECLARE v_subtotal DECIMAL(12,4);
    DECLARE v_costo_unitario_base DECIMAL(12,4);
    DECLARE v_cantidad_equivalente DECIMAL(12,4);
    DECLARE v_id_inventario INT;

    /* ========================================= */
    /* MANEJO DE ERRORES */
    /* ========================================= */

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        GET DIAGNOSTICS CONDITION 1 v_error = MESSAGE_TEXT;
        SET p_id_detalle_factura = NULL;
        SET p_mensaje = CONCAT('ERROR: ', v_error);
    END;

    START TRANSACTION;

    /* ========================================= */
    /* VALIDACIONES */
    /* ========================================= */
    IF p_vl_cantidad <= 0 OR p_vl_costo_unitario < 0
    THEN
        SET p_mensaje = 'ERROR: Cantidad o costo inválido';
        ROLLBACK;
        LEAVE proc;
    END IF;

    /* ========================================= */
    /* OBTENER EQUIVALENCIA PROVEEDOR */
    /* ========================================= */

    SELECT vl_cantidad_equivalente
    INTO v_cantidad_equivalente
    FROM productos_proveedor
    WHERE ad_productos_proveedor = p_fk_prodpro_ad_product_prove;

    IF v_cantidad_equivalente IS NULL
       OR v_cantidad_equivalente <= 0
    THEN
        SET p_mensaje = 'ERROR: Producto proveedor sin equivalencia';
        ROLLBACK;
        LEAVE proc;
    END IF;

    /* ========================================= */
    /* CALCULOS */
    /* ========================================= */

    SET v_subtotal = p_vl_cantidad * p_vl_costo_unitario;

    /* COSTO UNITARIO BASE
        Ejemplo:
        Caja = 12 unidades
        Caja cuesta 24000
        costo base = 24000 / 12 = 2000
    */

    SET v_costo_unitario_base = p_vl_costo_unitario / v_cantidad_equivalente;

    /* ========================================= */
    /* GENERAR ID DETALLE */
    /* ========================================= */

    SET p_id_detalle_factura = fn_actualiza_secuencias('seq_detalle_factura_compra');

    /* ========================================= */
    /* INSERT DETALLE FACTURA */
    /* ========================================= */

    INSERT INTO detalle_factura_compra (
        ad_detalle_factura,
        fk_factura_ad_factura,
        fk_product_ad_producto,
        fk_prodpro_ad_product_prove,
        vl_cantidad,
        vl_costo_unitario,
        vl_subtotal,
        vl_costo_unitario_base
    )
    VALUES (
        p_id_detalle_factura,
        p_fk_factura_ad_factura,
        p_fk_product_ad_producto,
        p_fk_prodpro_ad_product_prove,
        p_vl_cantidad,
        p_vl_costo_unitario,
        v_subtotal,
        v_costo_unitario_base
    );

    /* ========================================= */
    /* INSERT HISTORICO DE PRECIOS               */
    /* ========================================= */

    INSERT INTO historico_precios_proveedor (
        ad_historico,
        fk_propro_ad_prod_prov,
        vl_precio_unitario,
        dt_fecha_precio,
        observaciones
    )
    VALUES (
        fn_actualiza_secuencias('seq_historico_pre_prov'),
        p_fk_prodpro_ad_product_prove,
        p_vl_costo_unitario,
        CURDATE(),
        CONCAT('Precio registrado desde factura compra ID ', p_fk_factura_ad_factura)
	);

    /* ========================================= */
    /* INSERT INVENTARIO ENTRADA */
    /* ========================================= */

    SET v_id_inventario = fn_actualiza_secuencias('seq_inventario');

    INSERT INTO inventario (
        ad_inventario,
        fk_product_ad_producto,
        cl_tipo_movimiento,
        dt_movimiento,
        vl_cantidad,
        vl_costo_unitario,
        vl_cantidad_disponible,
        fk_referencia_origen,
        observaciones
    )
    VALUES (
        v_id_inventario,
        p_fk_product_ad_producto,
        'EN',
        NOW(),
        /* Cantidad REAL BASE */
        p_vl_cantidad * v_cantidad_equivalente,
        v_costo_unitario_base,
        /* Disponible inicial */
        p_vl_cantidad * v_cantidad_equivalente,
        p_fk_factura_ad_factura,
        CONCAT('Entrada por factura compra ID ', p_fk_factura_ad_factura)
    );

    COMMIT;

    SET p_mensaje =
        CONCAT('Detalle factura registrado correctamente. ID: ', p_id_detalle_factura);

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_gestionar_detalle_factura_pant` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_gestionar_detalle_factura_pant`(
    IN p_accion CHAR(1), -- I, U, D, C, V
    IN p_ad_detalle_factura INT,
    IN p_fk_factura_ad_factura INT,
    IN p_fk_product_ad_producto INT,
    IN p_fk_prodpro_ad_product_prove INT,
    IN p_vl_cantidad DECIMAL(12,4),
    IN p_vl_costo_unitario DECIMAL(12,4),
    OUT p_mensaje VARCHAR(255)
)
proc: BEGIN
    DECLARE v_ad_detalle INT;
    DECLARE v_existente INT DEFAULT 0;
    DECLARE v_error TEXT;
    DECLARE v_equivalencia DECIMAL(12,4);
    DECLARE v_subtotal DECIMAL(12,4);
    DECLARE v_costo_unitario_base DECIMAL(12,4);
    DECLARE v_ad_inventario INT;
    DECLARE v_cantidad_anterior DECIMAL(12,4);
    DECLARE v_disponible_actual DECIMAL(12,4);
    DECLARE v_diferencia DECIMAL(12,4);
    DECLARE v_inventario_id INT;
    DECLARE v_consumido DECIMAL(12,4);
    DECLARE v_fk_grupo_ad_grupo_producto INT;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 v_error = MESSAGE_TEXT;
        ROLLBACK;

        INSERT INTO log_errores (
            modulo, operacion, mensaje_error, datos_entrada
        ) VALUES (
            'sp_gestionar_detalle_factura_compra',
            p_accion,
            v_error,
            CONCAT(
                'factura=',IFNULL(p_fk_factura_ad_factura,'NULL'),
                '; producto=',IFNULL(p_fk_product_ad_producto,'NULL')
            )
        );

        SET p_mensaje = CONCAT('ERROR: ', v_error);
    END;

    /* ================= VALIDACIONES ================= */
    IF p_accion NOT IN ('I','U','D','C','V') THEN
        SET p_mensaje = 'ERROR: Acción inválida';
        LEAVE proc;
    END IF;

    IF p_accion IN ('I','U') THEN
        IF p_vl_cantidad <= 0 THEN
            SET p_mensaje = 'ERROR: Cantidad inválida';
            LEAVE proc;
        END IF;

        IF p_vl_costo_unitario <= 0 THEN
            SET p_mensaje = 'ERROR: Costo unitario inválido';
            LEAVE proc;
        END IF;
    END IF;

    /* ================= VALIDAR EXISTENCIA ================= */
    IF p_accion IN ('C','V','U','D') THEN
        SELECT COUNT(*)
        INTO v_existente
        FROM detalle_factura_compra
        WHERE ad_detalle_factura = p_ad_detalle_factura;
    END IF;

    /* ================= TRANSACCION ================= */
    IF p_accion IN ('I','U','D') THEN
        START TRANSACTION;
    END IF;

    /* ================= ACCIONES ================= */
    CASE p_accion

    /* ================= INSERTAR ================= */
    WHEN 'I' THEN
        /* validar estado factura */
        SELECT COUNT(*)
        INTO v_existente
        FROM factura_compra
        WHERE ad_factura = p_fk_factura_ad_factura
        AND ds_estado_factura = 'RE';
        
        IF v_existente = 0 THEN
            SET p_mensaje = 'ERROR: factura no puede ser modificada';
            ROLLBACK;
            LEAVE proc;
        END IF;
        
        SELECT COUNT(*)
        INTO v_existente
        FROM productos_proveedor
        WHERE ad_productos_proveedor = p_fk_prodpro_ad_product_prove
        AND fk_productos_ad_producto = p_fk_product_ad_producto;

        IF v_existente = 0 THEN
            SET p_mensaje = 'ERROR: el producto no coincide con el producto del proveedor';
            LEAVE proc;
        END IF;

        SELECT COUNT(*)
        INTO v_existente
        FROM detalle_factura_compra
        WHERE fk_factura_ad_factura = p_fk_factura_ad_factura
        AND fk_product_ad_producto = p_fk_product_ad_producto
		AND ad_detalle_factura <> IFNULL(p_ad_detalle_factura,0);

        IF v_existente > 0 THEN
            SET p_mensaje = 'ERROR: el producto ya existe en el detalle de la factura';
            LEAVE proc;
        END IF;

        /* obtener equivalencia proveedor */
        SELECT vl_cantidad_equivalente
        INTO v_equivalencia
        FROM productos_proveedor
        WHERE ad_productos_proveedor = p_fk_prodpro_ad_product_prove;

        IF v_equivalencia IS NULL OR v_equivalencia = 0 THEN
            SET p_mensaje = 'ERROR: equivalencia del producto proveedor inválida';
            ROLLBACK;
            LEAVE proc;
        END IF;

        SET v_subtotal = p_vl_cantidad * p_vl_costo_unitario;

        SET v_costo_unitario_base = p_vl_costo_unitario / v_equivalencia;

        SET v_ad_detalle = fn_actualiza_secuencias('seq_detalle_factura_compra');

        INSERT INTO detalle_factura_compra(
            ad_detalle_factura,
            fk_factura_ad_factura,
            fk_product_ad_producto,
            fk_prodpro_ad_product_prove,
            vl_cantidad,
            vl_costo_unitario,
            vl_subtotal,
            vl_costo_unitario_base
        )
        VALUES(
            v_ad_detalle,
            p_fk_factura_ad_factura,
            p_fk_product_ad_producto,
            p_fk_prodpro_ad_product_prove,
            p_vl_cantidad,
            p_vl_costo_unitario,
            v_subtotal,
            v_costo_unitario_base
        );

        SELECT sp.fk_grupo_ad_grupo_producto
        INTO v_fk_grupo_ad_grupo_producto
        FROM productos pr, subgrupo_producto sp
        WHERE pr.ad_producto = p_fk_product_ad_producto
        AND sp.ad_subgrupo_producto = pr.fk_subgrupo_ad_subgrupo_producto;

        IF v_fk_grupo_ad_grupo_producto <> 12 THEN
           /* ========================================= */
           /* INSERT HISTORICO DE PRECIOS               */
           /* ========================================= */

           INSERT INTO historico_precios_proveedor (
               ad_historico,
               fk_propro_ad_prod_prov,
               vl_precio_unitario,
               dt_fecha_precio,
               observaciones
           )
           VALUES (
               fn_actualiza_secuencias('seq_historico_pre_prov'),
               p_fk_prodpro_ad_product_prove,
               p_vl_costo_unitario,
               CURDATE(),
               CONCAT('Precio registrado desde factura compra ID ', p_fk_factura_ad_factura)
	       );

           /* ========================================= */
           /* INSERT INVENTARIO ENTRADA */
           /* ========================================= */

           SET v_ad_inventario = fn_actualiza_secuencias('seq_inventario');

           INSERT INTO inventario (
               ad_inventario,
               fk_product_ad_producto,
               cl_tipo_movimiento,
               dt_movimiento,
               vl_cantidad,
               vl_costo_unitario,
               vl_cantidad_disponible,
               fk_referencia_origen,
               fk_detalle_factura,
               observaciones
           )
           VALUES (
               v_ad_inventario,
               p_fk_product_ad_producto,
               'EN',
               NOW(),
               /* Cantidad REAL BASE */
               p_vl_cantidad * v_equivalencia,
               v_costo_unitario_base,
               /* Disponible inicial */
               p_vl_cantidad * v_equivalencia,
               p_fk_factura_ad_factura,
               v_ad_detalle,
               CONCAT('Entrada por factura compra ID ', p_fk_factura_ad_factura)
           );
        END IF;

        COMMIT;

        SET p_mensaje = 'Detalle de factura insertado correctamente';

    /* ================= ACTUALIZAR ================= */
    WHEN 'U' THEN
        IF v_existente = 0 THEN
            SET p_mensaje = 'ERROR: detalle no existe';
            ROLLBACK;
            LEAVE proc;
        END IF;
        
        SELECT ad_inventario,
               vl_cantidad,
               vl_cantidad_disponible
        INTO   v_inventario_id,
               v_cantidad_anterior,
               v_disponible_actual
		FROM inventario
        WHERE fk_detalle_factura = p_ad_detalle_factura
        AND cl_tipo_movimiento = 'EN'
        LIMIT 1;
        
        SET v_consumido = v_cantidad_anterior - v_disponible_actual;

        IF (p_vl_cantidad * v_equivalencia) < v_consumido THEN
           SET p_mensaje = 'ERROR: No puede reducir la cantidad porque parte del inventario ya fue consumido';
		   ROLLBACK;
           LEAVE proc;
        END IF;
        
        SET v_diferencia = (p_vl_cantidad * v_equivalencia) - v_cantidad_anterior;
        
        SELECT vl_cantidad_equivalente
        INTO v_equivalencia
        FROM productos_proveedor
        WHERE ad_productos_proveedor = p_fk_prodpro_ad_product_prove;

        SET v_subtotal = p_vl_cantidad * p_vl_costo_unitario;

        SET v_costo_unitario_base = p_vl_costo_unitario / v_equivalencia;

        UPDATE detalle_factura_compra
        SET fk_product_ad_producto = p_fk_product_ad_producto,
            fk_prodpro_ad_product_prove = p_fk_prodpro_ad_product_prove,
            vl_cantidad = p_vl_cantidad,
            vl_costo_unitario = p_vl_costo_unitario,
            vl_subtotal = v_subtotal,
            vl_costo_unitario_base = v_costo_unitario_base
        WHERE ad_detalle_factura = p_ad_detalle_factura;

        SELECT sp.fk_grupo_ad_grupo_producto
        INTO v_fk_grupo_ad_grupo_producto
        FROM productos pr, subgrupo_producto sp
        WHERE pr.ad_producto = p_fk_product_ad_producto
        AND sp.ad_subgrupo_producto = pr.fk_subgrupo_ad_subgrupo_producto;

        IF v_fk_grupo_ad_grupo_producto <> 12 THEN
           UPDATE inventario
           SET fk_product_ad_producto = p_fk_product_ad_producto,
               vl_cantidad = p_vl_cantidad * v_equivalencia,
               vl_cantidad_disponible = vl_cantidad_disponible + v_diferencia,
               vl_costo_unitario = v_costo_unitario_base,
               observaciones = CONCAT('Actualizado desde factura ', p_fk_factura_ad_factura)
           WHERE ad_inventario = v_inventario_id;

           /* ========================================= */
           /* INSERT HISTORICO DE PRECIOS               */
           /* ========================================= */

           INSERT INTO historico_precios_proveedor (
               ad_historico,
               fk_propro_ad_prod_prov,
               vl_precio_unitario,
               dt_fecha_precio,
               observaciones
           )
           VALUES (
               fn_actualiza_secuencias('seq_historico_pre_prov'),
               p_fk_prodpro_ad_product_prove,
               p_vl_costo_unitario,
               CURDATE(),
               CONCAT('Precio registrado desde factura compra ID ', p_fk_factura_ad_factura)
	       );
        END IF;

        COMMIT;

        SET p_mensaje = 'Detalle actualizado correctamente';

    /* ================= ELIMINAR ================= */
    WHEN 'D' THEN
        IF v_existente = 0 THEN
            SET p_mensaje = 'ERROR: detalle no existe';
            ROLLBACK;
            LEAVE proc;
        END IF;
        
        SELECT sp.fk_grupo_ad_grupo_producto
        INTO v_fk_grupo_ad_grupo_producto
        FROM productos pr, subgrupo_producto sp
        WHERE pr.ad_producto = p_fk_product_ad_producto
        AND sp.ad_subgrupo_producto = pr.fk_subgrupo_ad_subgrupo_producto;

        IF v_fk_grupo_ad_grupo_producto <> 12 THEN

           SELECT ad_inventario,
                  vl_cantidad,
                  vl_cantidad_disponible
           INTO   v_inventario_id,
                  v_cantidad_anterior,
                  v_disponible_actual
           FROM inventario
		   WHERE fk_detalle_factura = p_ad_detalle_factura
           AND cl_tipo_movimiento = 'EN'
		   LIMIT 1;
        
           IF v_inventario_id IS NULL THEN
              SET p_mensaje = 'ERROR: No existe movimiento inventario asociado';
              ROLLBACK;
              LEAVE proc;
           END IF;

           SET v_consumido = v_cantidad_anterior - v_disponible_actual;
        
           IF v_consumido > 0 THEN
              SET p_mensaje = 'ERROR: No puede eliminar el detalle porque el inventario ya tuvo movimientos de salida';
		      ROLLBACK;
              LEAVE proc;
           END IF;
        
           DELETE FROM inventario
           WHERE ad_inventario = v_inventario_id;
        END IF;
        
		DELETE FROM detalle_factura_compra
        WHERE ad_detalle_factura = p_ad_detalle_factura;

        COMMIT;

        SET p_mensaje = 'Detalle eliminado correctamente';

    /* ================= CONSULTAR ================= */
    WHEN 'C' THEN
        SELECT *
        FROM detalle_factura_compra
        WHERE fk_factura_ad_factura = p_fk_factura_ad_factura;

        SET p_mensaje = 'Consulta realizada correctamente';

    /* ================= VALIDAR ================= */
    WHEN 'V' THEN
        IF v_existente > 0 THEN
            SET p_mensaje = 'Detalle existe';
        ELSE
            SET p_mensaje = 'Detalle NO existe';
        END IF;

    END CASE;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_gestionar_detalle_orden_compra` */;
