DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_gestionar_factura_compra`(
    IN p_accion CHAR(1),
    IN p_ad_factura INT,
    IN p_fk_provee_ad_proveedor INT,
    IN p_fk_sucursal_ad_sucursal INT,
    IN p_fk_ordencom_ad_orden INT,
    IN p_ds_numero_factura VARCHAR(45),
    IN p_dt_fecha_factura DATE,
    IN p_vl_descuento DECIMAL(12,4),
    IN p_vl_impuestos DECIMAL(12,4),
    IN p_vl_retencion DECIMAL(12,4),
    IN p_ds_observaciones TEXT,
    OUT p_mensaje VARCHAR(255)
)
proc: BEGIN
    DECLARE v_error TEXT;
    DECLARE v_existente INT DEFAULT 0;
    DECLARE v_ad_factura INT DEFAULT 0;
    DECLARE v_total_detalle DECIMAL(12,4) DEFAULT 0;
    DECLARE v_tiene_detalle INT DEFAULT 0;
    DECLARE v_tiene_pagos INT DEFAULT 0;

    /* =========================
       MANEJO DE ERRORES
    ========================== */

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 v_error = MESSAGE_TEXT;
        ROLLBACK;

        INSERT INTO log_errores (
            modulo,
            operacion,
            mensaje_error,
            datos_entrada
        )
        VALUES (
            'sp_gestionar_factura_compra',
            p_accion,
            v_error,
            CONCAT(
                'factura=',IFNULL(p_ad_factura,'NULL'),
                '; proveedor=',IFNULL(p_fk_provee_ad_proveedor,'NULL'),
                '; numero=',IFNULL(p_ds_numero_factura,'NULL')
            )
        );

        SET p_mensaje = CONCAT('ERROR: ', v_error);
    END;

    /* =========================
       VALIDAR ACCION
    ========================== */

    IF p_accion NOT IN ('I','U','A','C','V') THEN
        SET p_mensaje = 'ERROR: Acción inválida';
        LEAVE proc;
    END IF;

    /* =========================
       VALIDAR EXISTENCIA
    ========================== */

    IF p_accion IN ('U','A','V') THEN
        SELECT COUNT(*)
        INTO v_existente
        FROM factura_compra
        WHERE ad_factura = p_ad_factura;

        IF v_existente = 0 THEN
            SET p_mensaje = 'ERROR: factura no existe';
            LEAVE proc;
        END IF;
    END IF;

    /* =========================
       TRANSACCION
    ========================== */

    IF p_accion IN ('I','U','A') THEN
        START TRANSACTION;
    END IF;

    /* =========================
       ACCIONES
    ========================== */

    CASE p_accion

    /* =====================================================
       INSERTAR
    ===================================================== */

    WHEN 'I' THEN
        /* VALIDAR DUPLICADO */

        SELECT COUNT(*)
        INTO v_existente
        FROM factura_compra
        WHERE fk_provee_ad_proveedor = p_fk_provee_ad_proveedor
        AND ds_numero_factura = p_ds_numero_factura;

        IF v_existente > 0 THEN
            SET p_mensaje = 'ERROR: Ya existe una factura con ese número para el proveedor';
            ROLLBACK;
            LEAVE proc;
        END IF;

        SET v_ad_factura = fn_actualiza_secuencias('seq_factura_compra');

        INSERT INTO factura_compra (
            ad_factura,
            fk_provee_ad_proveedor,
            fk_sucursal_ad_sucursal,
            fk_ordencom_ad_orden,
            ds_numero_factura,
            dt_fecha_factura,
            vl_facturado,
            vl_descuento,
            vl_impuestos,
            vl_retencion,
            vl_total,
            vl_pagado,
            vl_saldo,
            ds_estado_factura,
            ds_estado_pago,
            ds_observaciones,
            ic_cuenta_cobro
        )
        VALUES (
            v_ad_factura,
            p_fk_provee_ad_proveedor,
            p_fk_sucursal_ad_sucursal,
            p_fk_ordencom_ad_orden,
            p_ds_numero_factura,
            p_dt_fecha_factura,
            0,
            p_vl_descuento,
            p_vl_impuestos,
            p_vl_retencion,
            0,
            0,
            0,
            'RE',
            'PE',
            p_ds_observaciones,
            'N'
        );

        COMMIT;

        SET p_mensaje = CONCAT('Factura registrada correctamente. ID: ', v_ad_factura);

    /* =====================================================
       ACTUALIZAR
    ===================================================== */

    WHEN 'U' THEN
        /* VALIDAR SI TIENE DETALLE */

        SELECT COUNT(*)
        INTO v_tiene_detalle
        FROM detalle_factura_compra
        WHERE fk_factura_ad_factura = p_ad_factura;

        /* SI TIENE DETALLE
           NO permitir cambios estructurales */

        IF v_tiene_detalle > 0 THEN
            UPDATE factura_compra
            SET dt_fecha_factura = p_dt_fecha_factura,
                vl_descuento = p_vl_descuento,
                vl_impuestos = p_vl_impuestos,
                vl_retencion = p_vl_retencion,
                ds_observaciones = p_ds_observaciones
            WHERE ad_factura = p_ad_factura;
        ELSE
            UPDATE factura_compra
            SET fk_provee_ad_proveedor = p_fk_provee_ad_proveedor,
                fk_sucursal_ad_sucursal = p_fk_sucursal_ad_sucursal,
                fk_ordencom_ad_orden = p_fk_ordencom_ad_orden,
                ds_numero_factura = p_ds_numero_factura,
                dt_fecha_factura = p_dt_fecha_factura,
                vl_descuento = p_vl_descuento,
                vl_impuestos = p_vl_impuestos,
                vl_retencion = p_vl_retencion,
                ds_observaciones = p_ds_observaciones
            WHERE ad_factura = p_ad_factura;
        END IF;

        /* RECALCULAR TOTAL */

        SELECT IFNULL(SUM(vl_subtotal),0)
        INTO v_total_detalle
        FROM detalle_factura_compra
        WHERE fk_factura_ad_factura = p_ad_factura;

        UPDATE factura_compra
        SET vl_facturado = v_total_detalle,
            vl_total =
                v_total_detalle
                - vl_descuento
                + vl_impuestos
                - vl_retencion,
            vl_saldo =
                (
                    v_total_detalle
                    - vl_descuento
                    + vl_impuestos
                    - vl_retencion
                ) - vl_pagado
        WHERE ad_factura = p_ad_factura;

        COMMIT;

        SET p_mensaje = 'Factura actualizada correctamente';

    /* =====================================================
       ANULAR
    ===================================================== */

    WHEN 'A' THEN

        /* VALIDAR PAGOS */

        IF EXISTS (
            SELECT 1
            FROM factura_compra
            WHERE ad_factura = p_ad_factura
            AND vl_pagado > 0
        ) THEN
            SET p_mensaje = 'ERROR: No puede anular una factura con pagos registrados';
            ROLLBACK;
            LEAVE proc;
        END IF;

        /* CAMBIAR ESTADO */

        UPDATE factura_compra
        SET ds_estado_factura = 'AN',
            ds_estado_pago = 'AN'
        WHERE ad_factura = p_ad_factura;

        COMMIT;

        SET p_mensaje = 'Factura anulada correctamente';

    /* =====================================================
       CONSULTAR
    ===================================================== */

    WHEN 'C' THEN
        SELECT *
        FROM factura_compra
        WHERE (
            ad_factura = p_ad_factura
            OR p_ad_factura IS NULL
        )
        ORDER BY ad_factura DESC;

        SET p_mensaje = 'Consulta realizada correctamente';

    /* =====================================================
       VALIDAR
    ===================================================== */

    WHEN 'V' THEN
        IF v_existente > 0 THEN
            SET p_mensaje = 'Factura existe';
        ELSE
            SET p_mensaje = 'Factura NO existe';
        END IF;

    END CASE;

END proc ;;
DELIMITER ;
