CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_gestionar_grupo_producto`(
    IN p_accion CHAR(1),                 -- I, U, D, C, V
    IN p_ad_grupo_producto INT,
    IN p_ds_nombre_grupo VARCHAR(45),
    OUT p_mensaje VARCHAR(255)
)
proc: BEGIN
    DECLARE v_existente INT DEFAULT 0;
    DECLARE v_ad_grupo_producto INT;
    DECLARE v_error TEXT;

    /* =========================
       MANEJO DE ERRORES
    ==========================*/
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 v_error = MESSAGE_TEXT;
        ROLLBACK;
        SET p_mensaje = CONCAT('ERROR: ', v_error);
    END;

    /* =========================
       VALIDAR ACCIÓN
    ==========================*/
    IF p_accion NOT IN ('I','U','D','C','V') THEN
        SET p_mensaje = 'ERROR: Acción no válida (I,U,D,C,V)';
        LEAVE proc;
    END IF;

    /* =========================
       VALIDAR EXISTENCIA POR NOMBRE
    ==========================*/
    IF p_accion IN ('I','V') THEN
        SELECT COUNT(*)
        INTO v_existente
        FROM grupo_producto
        WHERE ds_nombre_grupo = p_ds_nombre_grupo;
    END IF;

    /* =========================
       INICIAR TRANSACCIÓN
    ==========================*/
    IF p_accion IN ('I','U','D') THEN
        START TRANSACTION;
    END IF;

    /* =========================
       LÓGICA PRINCIPAL
    ==========================*/
    CASE p_accion

        /* ========= INSERTAR ========= */
        WHEN 'I' THEN
            IF p_ds_nombre_grupo IS NULL OR TRIM(p_ds_nombre_grupo) = '' THEN
                SET p_mensaje = 'ERROR: El nombre del grupo es obligatorio';
                ROLLBACK;
                LEAVE proc;
            END IF;

            IF v_existente > 0 THEN
                SET p_mensaje = 'ERROR: Ya existe un grupo con ese nombre';
                ROLLBACK;
                LEAVE proc;
            END IF;

            SET v_ad_grupo_producto = fn_actualiza_secuencias('seq_grupo_producto');

            INSERT INTO grupo_producto (
                ad_grupo_producto,
                ds_nombre_grupo
            ) VALUES (
                v_ad_grupo_producto,
                p_ds_nombre_grupo
            );

            COMMIT;
            SET p_mensaje = CONCAT('Grupo de producto creado correctamente. ID: ', v_ad_grupo_producto);

        /* ========= ACTUALIZAR ========= */
        WHEN 'U' THEN
            IF p_ad_grupo_producto IS NULL THEN
                SET p_mensaje = 'ERROR: Debe indicar el ID del grupo';
                ROLLBACK;
                LEAVE proc;
            END IF;

            UPDATE grupo_producto
            SET ds_nombre_grupo = p_ds_nombre_grupo
            WHERE ad_grupo_producto = p_ad_grupo_producto;

            IF ROW_COUNT() = 0 THEN
                SET p_mensaje = 'ERROR: Grupo no encontrado o sin cambios';
                ROLLBACK;
                LEAVE proc;
            END IF;

            COMMIT;
            SET p_mensaje = 'Grupo de producto actualizado correctamente';

        /* ========= ELIMINAR ========= */
        WHEN 'D' THEN
            IF p_ad_grupo_producto IS NULL THEN
                SET p_mensaje = 'ERROR: Debe indicar el ID del grupo';
                ROLLBACK;
                LEAVE proc;
            END IF;

            /* Validar que no esté en uso */
            IF EXISTS (
                SELECT 1
                FROM productos
                WHERE fk_grupo_ad_grupo = p_ad_grupo_producto
            ) THEN
                SET p_mensaje = 'ERROR: No se puede eliminar el grupo porque está asociado a productos';
                ROLLBACK;
                LEAVE proc;
            END IF;

            DELETE FROM grupo_producto
            WHERE ad_grupo_producto = p_ad_grupo_producto;

            IF ROW_COUNT() = 0 THEN
                SET p_mensaje = 'ERROR: Grupo no encontrado';
                ROLLBACK;
                LEAVE proc;
            END IF;

            COMMIT;
            SET p_mensaje = 'Grupo de producto eliminado correctamente';

        /* ========= CONSULTAR ========= */
        WHEN 'C' THEN
            SELECT ad_grupo_producto,
                   ds_nombre_grupo
            FROM grupo_producto
            ORDER BY ds_nombre_grupo;

            SET p_mensaje = 'Consulta realizada correctamente';

        /* ========= VALIDAR EXISTENCIA ========= */
        WHEN 'V' THEN
            IF v_existente > 0 THEN
                SET p_mensaje = 'Grupo existe: SI';
            ELSE
                SET p_mensaje = 'Grupo existe: NO';
            END IF;

    END CASE;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
