CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_gestionar_permiso_acceso`(
    IN p_accion CHAR(1), -- I,U,D,C,V
    IN p_ad_permiso_acceso INT,
    IN p_ds_codigo VARCHAR(50),
    IN p_ds_nombre_permiso VARCHAR(100),
    IN p_ds_modulo VARCHAR(50),
    IN p_usuario_auditoria INT,
    IN p_ds_ip VARCHAR(45),
    OUT p_mensaje VARCHAR(255)
)
proc: BEGIN
    DECLARE v_existente INT DEFAULT 0;
    DECLARE v_ad_permiso INT DEFAULT 0;
    DECLARE v_error TEXT;

    /* =========================
       MANEJO DE ERRORES
    ==========================*/
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1
        v_error = MESSAGE_TEXT;
        ROLLBACK;

        INSERT INTO log_errores (
            modulo,
            operacion,
            mensaje_error,
            datos_entrada
        )
        VALUES (
            'sp_gestionar_permiso_acceso',
            p_accion,
            v_error,
            CONCAT(
                'ad_permiso=', IFNULL(p_ad_permiso_acceso,'NULL'), '; ',
                'codigo=', IFNULL(p_ds_codigo,'NULL'), '; ',
                'nombre=', IFNULL(p_ds_nombre_permiso,'NULL')
            )
        );

        SET p_mensaje = CONCAT('ERROR: ', v_error);
    END;

    /* =========================
       VALIDAR ACCIÓN
    ==========================*/
    IF p_accion NOT IN ('I','U','D','C','V') THEN
        SET p_mensaje = 'ERROR: Acción no válida. Use I,U,D,C,V';
        LEAVE proc;
    END IF;

    /* =========================
       VALIDAR EXISTENCIA
    ==========================*/
    IF p_accion IN ('I','V') THEN
        SELECT COUNT(*)
        INTO v_existente
        FROM permiso_acceso
        WHERE ds_codigo = p_ds_codigo
          AND ic_registro_activo = 'Y';
    END IF;

    /* =========================
       TRANSACCIÓN
    ==========================*/
    IF p_accion IN ('I','U','D') THEN
        START TRANSACTION;
    END IF;

    /* =========================
       LÓGICA PRINCIPAL
    ==========================*/
    CASE p_accion
        /* =====================
           INSERTAR
        ======================*/
        WHEN 'I' THEN
            IF v_existente > 0 THEN
                SET p_mensaje = 'ERROR: Ya existe un permiso activo con ese código';
                ROLLBACK;
                LEAVE proc;
            END IF;

            SET v_ad_permiso = fn_actualiza_secuencias('seq_permiso_acceso');

            INSERT INTO permiso_acceso (
                ad_permiso_acceso,
                ds_codigo,
                ds_nombre_permiso,
                ds_modulo,
                ic_registro_activo
            )
            VALUES (
                v_ad_permiso,
                p_ds_codigo,
                p_ds_nombre_permiso,
                p_ds_modulo,
                'Y'
            );

            CALL sp_registrar_auditoria(
                p_usuario_auditoria,
                'SEGURIDAD',
                'CREAR',
                'permiso_acceso',
                v_ad_permiso,
                CONCAT('Permiso de Acceso registrado: ', p_ds_nombre_permiso),
                p_ds_ip
            );

            COMMIT;

            SET p_mensaje = CONCAT('Permiso registrado correctamente. ID: ', v_ad_permiso);

        /* =====================
           ACTUALIZAR
        ======================*/
        WHEN 'U' THEN
            IF p_ad_permiso_acceso IS NULL THEN
                SET p_mensaje = 'ERROR: Debe indicar el ID del permiso';
                ROLLBACK;
                LEAVE proc;
            END IF;

            UPDATE permiso_acceso
            SET ds_codigo = p_ds_codigo,
                ds_nombre_permiso = p_ds_nombre_permiso,
                ds_modulo = p_ds_modulo
            WHERE ad_permiso_acceso = p_ad_permiso_acceso;

            IF ROW_COUNT() = 0 THEN
                SET p_mensaje = 'ERROR: Permiso no encontrado o sin cambios';
                ROLLBACK;
                LEAVE proc;
            END IF;

            CALL sp_registrar_auditoria(
                p_usuario_auditoria,
                'SEGURIDAD',
                'ACTUALIZAR',
                'permiso_acceso',
                p_ad_permiso_acceso,
                CONCAT('Permiso de Acceso actualizado: ', p_ds_nombre_permiso),
                p_ds_ip
            );
            
            COMMIT;

            SET p_mensaje = 'Permiso actualizado correctamente';

        /* =====================
           DESACTIVAR
        ======================*/
        WHEN 'D' THEN
            IF p_ad_permiso_acceso IS NULL THEN
                SET p_mensaje = 'ERROR: Debe indicar el ID del permiso';
                ROLLBACK;
                LEAVE proc;
            END IF;

            UPDATE permiso_acceso
            SET ic_registro_activo = 'N'
            WHERE ad_permiso_acceso = p_ad_permiso_acceso;

            IF ROW_COUNT() = 0 THEN
                SET p_mensaje = 'ERROR: Permiso no encontrado';
                ROLLBACK;
                LEAVE proc;
            END IF;

            CALL sp_registrar_auditoria(
                p_usuario_auditoria,
                'SEGURIDAD',
                'DESACTIVAR',
                'permiso_acceso',
                p_ad_permiso_acceso,
                CONCAT('Permiso de Acceso desactivado ID ', p_ad_permiso_acceso),
                p_ds_ip
            );

            COMMIT;

            SET p_mensaje = 'Permiso desactivado correctamente';

        /* =====================
           CONSULTAR
        ======================*/
        WHEN 'C' THEN
            IF p_ad_permiso_acceso IS NULL THEN
                SELECT *
                FROM permiso_acceso
                WHERE ic_registro_activo = 'Y'
                ORDER BY ds_modulo,
                         ds_nombre_permiso;
            ELSE
                SELECT *
                FROM permiso_acceso
                WHERE ad_permiso_acceso = p_ad_permiso_acceso;
            END IF;

            SET p_mensaje = 'Consulta realizada correctamente';

        /* =====================
           VALIDAR EXISTENCIA
        ======================*/
        WHEN 'V' THEN
            IF v_existente > 0 THEN
                SET p_mensaje = 'Permiso existe: SI';
            ELSE
                SET p_mensaje = 'Permiso existe: NO';
            END IF;
    END CASE;
END ;;
DELIMITER ;
