CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_gestionar_producto`(
    IN p_accion CHAR(1),  -- I, U, D, C, V
    IN p_ad_producto INT,
    IN p_fk_subgrupo_ad_subgrupo_producto INT,
    IN p_nm_producto VARCHAR(100),
    IN p_cl_unidad_base VARCHAR(2),
    IN p_ds_observaciones VARCHAR(100),
    IN p_nm_cuenta_puc INT,
    OUT p_mensaje VARCHAR(255)
)
proc: BEGIN
    DECLARE v_ad_producto INT DEFAULT 0;
    DECLARE v_existente INT DEFAULT 0;
    DECLARE v_subgrupo INT DEFAULT 0;
    DECLARE v_error TEXT;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 v_error = MESSAGE_TEXT;
        ROLLBACK;

        INSERT INTO log_errores (
            modulo, operacion, mensaje_error, datos_entrada
        ) VALUES (
            'sp_gestionar_producto',
            p_accion,
            v_error,
            CONCAT(
                'ad_producto=', IFNULL(p_ad_producto,'NULL'), '; ',
                'subgrupo=', IFNULL(p_fk_subgrupo_ad_subgrupo_producto,'NULL')
            )
        );

        SET p_mensaje = CONCAT('ERROR: ', v_error);
    END;

    -- Validaciones generales
    IF p_accion NOT IN ('I','U','D','C','V') THEN
        SET p_mensaje = 'ERROR: Acción no válida';
        LEAVE proc;
    END IF;

    -- Validar subgrupo
    IF p_accion IN ('I','U') THEN
        SELECT COUNT(*) INTO v_subgrupo
        FROM subgrupo_producto
        WHERE ad_subgrupo_producto = p_fk_subgrupo_ad_subgrupo_producto;

        IF v_subgrupo = 0 THEN
            SET p_mensaje = 'ERROR: Subgrupo de producto no existe';
            LEAVE proc;
        END IF;
    END IF;

    IF p_accion IN ('I','U','D') THEN
        START TRANSACTION;
    END IF;

    CASE p_accion

        WHEN 'I' THEN
            SET v_ad_producto = fn_actualiza_secuencias('seq_producto');

            INSERT INTO productos (
                ad_producto,
                nm_producto,
                cl_unidad_base,
                ds_observaciones,
                nm_cuenta_puc,
                fk_subgrupo_ad_subgrupo_producto
            ) VALUES (
                v_ad_producto,
                p_nm_producto,
                p_cl_unidad_base,
                p_ds_observaciones,
                p_nm_cuenta_puc,
                p_fk_subgrupo_ad_subgrupo_producto
            );

            COMMIT;
            SET p_mensaje = 'Producto insertado correctamente';

        WHEN 'U' THEN
            IF p_ad_producto IS NULL THEN
                SET p_mensaje = 'ERROR: ID del producto requerido';
                ROLLBACK;
                LEAVE proc;
            END IF;

            UPDATE productos
            SET nm_producto = p_nm_producto,
                cl_unidad_base = p_cl_unidad_base,
                ds_observaciones = p_ds_observaciones,
                nm_cuenta_puc = p_nm_cuenta_puc,
                fk_subgrupo_ad_subgrupo_producto = p_fk_subgrupo_ad_subgrupo_producto
            WHERE ad_producto = p_ad_producto;

            IF ROW_COUNT() = 0 THEN
                SET p_mensaje = 'ERROR: Producto no encontrado o sin cambios';
                ROLLBACK;
                LEAVE proc;
            END IF;

            COMMIT;
            SET p_mensaje = 'Producto actualizado correctamente';

        WHEN 'D' THEN
            DELETE FROM productos WHERE ad_producto = p_ad_producto;

            IF ROW_COUNT() = 0 THEN
                SET p_mensaje = 'ERROR: Producto no encontrado';
                ROLLBACK;
                LEAVE proc;
            END IF;

            COMMIT;
            SET p_mensaje = 'Producto eliminado correctamente';

        WHEN 'C' THEN
            SELECT p.*,
                   sg.ds_nombre AS ds_subgrupo,
                   g.ds_nombre_grupo
            FROM productos p
            JOIN subgrupo_producto sg
                 ON sg.ad_subgrupo_producto = p.fk_subgrupo_ad_subgrupo_producto
            JOIN grupo_producto g
                 ON g.ad_grupo_producto = sg.fk_grupo_ad_grupo_producto
            WHERE p.ad_producto = p_ad_producto;

            SET p_mensaje = 'Consulta realizada correctamente';

        WHEN 'V' THEN
            SELECT COUNT(*) INTO v_existente
            FROM productos
            WHERE ad_producto = p_ad_producto;

            SET p_mensaje = IF(v_existente > 0, 'Producto existe: SI', 'Producto existe: NO');
    END CASE;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
