CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_gestionar_productos_proveedor`(
    IN p_accion CHAR(1),   -- I, U, D, C, V
    IN p_ad_productos_proveedor INT,
    IN p_fk_productos_ad_producto INT,
    IN p_fk_proveedor_ad_proveedor INT,
    IN p_ds_producto_proveedor VARCHAR(100),
    IN p_vl_cantidad_equivalente DECIMAL(12,4),
    OUT p_mensaje VARCHAR(255)
)
proc: BEGIN
    DECLARE v_existente INT DEFAULT 0;
    DECLARE v_ad_productos_proveedor INT DEFAULT 0;
    DECLARE v_error TEXT;

    /* ==========================
       MANEJO DE ERRORES
    ========================== */
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 v_error = MESSAGE_TEXT;
        ROLLBACK;

        INSERT INTO log_errores (
            modulo, operacion, mensaje_error, datos_entrada
        ) VALUES (
            'sp_gestionar_productos_proveedor',
            p_accion,
            v_error,
            CONCAT(
                'producto=', IFNULL(p_fk_productos_ad_producto,'NULL'), '; ',
                'proveedor=', IFNULL(p_fk_proveedor_ad_proveedor,'NULL')
            )
        );

        SET p_mensaje = CONCAT('ERROR: ', v_error);
    END;

    /* ==========================
       VALIDACIONES GENERALES
    ========================== */
    IF p_accion NOT IN ('I','U','D','C','V') THEN
        SET p_mensaje = 'ERROR: Acción inválida';
        LEAVE proc;
    END IF;

    IF p_accion IN ('I','U') THEN
        IF p_fk_productos_ad_producto IS NULL
           OR p_fk_proveedor_ad_proveedor IS NULL THEN
            SET p_mensaje = 'ERROR: Producto y proveedor son obligatorios';
            LEAVE proc;
        END IF;

        IF p_vl_cantidad_equivalente <= 0 THEN
            SET p_mensaje = 'ERROR: La cantidad equivalente debe ser mayor a cero';
            LEAVE proc;
        END IF;
    END IF;

    /* ==========================
       VALIDAR EXISTENCIA
    ========================== */
    IF p_accion IN ('I','V','C') THEN
        SELECT COUNT(*) INTO v_existente
        FROM productos_proveedor
        WHERE fk_productos_ad_producto = p_fk_productos_ad_producto
          AND fk_proveedor_ad_proveedor = p_fk_proveedor_ad_proveedor;
    END IF;

    IF p_accion IN ('I','U','D') THEN
        START TRANSACTION;
    END IF;

    /* ==========================
       ACCIONES
    ========================== */
    CASE p_accion

        WHEN 'I' THEN
            IF v_existente > 0 THEN
                SET p_mensaje = 'ERROR: Ya existe el producto para este proveedor';
                ROLLBACK;
                LEAVE proc;
            END IF;

            SET v_ad_productos_proveedor = fn_actualiza_secuencias('seq_productos_proveedor');

            INSERT INTO productos_proveedor (
                ad_productos_proveedor,
                fk_productos_ad_producto,
                fk_proveedor_ad_proveedor,
                ds_producto_proveedor,
                vl_cantidad_equivalente
            ) VALUES (
                v_ad_productos_proveedor,
                p_fk_productos_ad_producto,
                p_fk_proveedor_ad_proveedor,
                p_ds_producto_proveedor,
                p_vl_cantidad_equivalente
            );

            COMMIT;
            SET p_mensaje = 'Producto proveedor creado correctamente';

        WHEN 'U' THEN
            IF p_ad_productos_proveedor IS NULL THEN
                SET p_mensaje = 'ERROR: Debe indicar el ID del registro';
                ROLLBACK;
                LEAVE proc;
            END IF;

            UPDATE productos_proveedor
            SET ds_producto_proveedor = p_ds_producto_proveedor,
                vl_cantidad_equivalente = p_vl_cantidad_equivalente
            WHERE ad_productos_proveedor = p_ad_productos_proveedor;

            IF ROW_COUNT() = 0 THEN
                SET p_mensaje = 'ERROR: Registro no encontrado o sin cambios';
                ROLLBACK;
                LEAVE proc;
            END IF;

            COMMIT;
            SET p_mensaje = 'Producto proveedor actualizado correctamente';

        WHEN 'D' THEN
            IF p_ad_productos_proveedor IS NULL THEN
                SET p_mensaje = 'ERROR: Debe indicar el ID del registro';
                ROLLBACK;
                LEAVE proc;
            END IF;

            DELETE FROM productos_proveedor
            WHERE ad_productos_proveedor = p_ad_productos_proveedor;

            IF ROW_COUNT() = 0 THEN
                SET p_mensaje = 'ERROR: Registro no encontrado';
                ROLLBACK;
                LEAVE proc;
            END IF;

            COMMIT;
            SET p_mensaje = 'Producto proveedor eliminado correctamente';

        WHEN 'C' THEN
            SELECT pp.*,
                   p.nm_producto,
                   pr.ds_razon_social
            FROM productos_proveedor pp
            JOIN productos p ON p.ad_producto = pp.fk_productos_ad_producto
            JOIN proveedor pr ON pr.ad_proveedor = pp.fk_proveedor_ad_proveedor
            WHERE pp.fk_productos_ad_producto = p_fk_productos_ad_producto;

            SET p_mensaje = 'Consulta realizada correctamente';

        WHEN 'V' THEN
            SET p_mensaje = IF(v_existente > 0,
                               'Relación producto-proveedor existe',
                               'Relación producto-proveedor no existe');
    END CASE;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_gestionar_proveedor` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
