CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_gestionar_proveedor`(
    IN p_accion CHAR(1),               -- I, U, D, C, V
    IN p_ad_proveedor INT,
    IN p_cl_tipo_identificacion VARCHAR(2),
    IN p_ds_identificacion VARCHAR(20),
    IN p_nm_digito_verificacion INT,
    IN p_ds_razon_social VARCHAR(80),
    IN p_ds_nombre_comercial VARCHAR(80),
    IN p_ds_direccion VARCHAR(100),
    IN p_ds_ciudad VARCHAR(45),
    IN p_ds_correo_electronico VARCHAR(100),
    IN p_ds_pagina_web VARCHAR(45),
    IN p_ds_telefono VARCHAR(45),
    IN p_cl_tipo_proveedor VARCHAR(2),
    IN p_cl_tipo_persona VARCHAR(2),
    IN p_cl_condicion_pago VARCHAR(2),
    IN p_nm_dias_pago INT,
    IN p_ic_responsable_iva VARCHAR(2),
    IN p_ic_aplica_retencion VARCHAR(2),
    IN p_ic_aplica_IVA VARCHAR(2),
	IN p_ic_precio_con_iva VARCHAR(2),
    IN p_ic_aplica_ICA VARCHAR(2),
    IN p_ds_contacto VARCHAR(45),
    IN p_nm_cuenta_puc INT,
    OUT p_mensaje VARCHAR(255)
)
proc: BEGIN
    DECLARE v_existente INT DEFAULT 0;
    DECLARE v_ad_proveedor INT DEFAULT 0;
    DECLARE v_error TEXT;

    /* ==========================
       MANEJO DE ERRORES
    ========================== */
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 v_error = MESSAGE_TEXT;
        ROLLBACK;

        INSERT INTO log_errores (
            modulo, operacion, mensaje_error, datos_entrada
        ) VALUES (
            'sp_gestionar_proveedor',
            p_accion,
            v_error,
            CONCAT(
                'id=', IFNULL(p_ad_proveedor,'NULL'), '; ',
                'identificacion=', IFNULL(p_ds_identificacion,'NULL')
            )
        );

        SET p_mensaje = CONCAT('ERROR: ', v_error);
    END;

    /* ==========================
       VALIDACIONES GENERALES
    ========================== */
    IF p_accion NOT IN ('I','U','D','C','V') THEN
        SET p_mensaje = 'ERROR: Acción inválida';
        LEAVE proc;
    END IF;

    IF p_accion IN ('I','U') THEN
        IF p_cl_tipo_identificacion NOT IN ('NI','CC') THEN
            SET p_mensaje = 'ERROR: Tipo identificación inválido';
            LEAVE proc;
        END IF;

        IF p_cl_tipo_persona NOT IN ('JU','NA') THEN
            SET p_mensaje = 'ERROR: Tipo persona inválido';
            LEAVE proc;
        END IF;

        IF p_ic_responsable_iva NOT IN ('SI','NO')
           OR p_ic_aplica_retencion NOT IN ('SI','NO')
           OR p_ic_aplica_IVA NOT IN ('SI','NO')
           OR p_ic_aplica_ICA NOT IN ('SI','NO') THEN
            SET p_mensaje = 'ERROR: Valores SI/NO inválidos en impuestos';
            LEAVE proc;
        END IF;
    END IF;

    /* ==========================
       VALIDAR EXISTENCIA
    ========================== */
    IF p_accion IN ('I','V','C') THEN
        SELECT COUNT(*) INTO v_existente
        FROM proveedor
        WHERE ds_identificacion = p_ds_identificacion
          AND ic_registro_activo = 'Y';
    END IF;

    IF p_accion IN ('I','U','D') THEN
        START TRANSACTION;
    END IF;

    /* ==========================
       ACCIONES
    ========================== */
    CASE p_accion

        WHEN 'I' THEN
            IF v_existente > 0 THEN
                SET p_mensaje = 'ERROR: Proveedor ya existe';
                ROLLBACK;
                LEAVE proc;
            END IF;

            SET v_ad_proveedor = fn_actualiza_secuencias('seq_proveedor');

            INSERT INTO proveedor (
                ad_proveedor,
                cl_tipo_identificacion,
                ds_identificacion,
                nm_digito_verificacion,
                ds_razon_social,
                ds_nombre_comercial,
                ds_direccion,
                ds_ciudad,
                ds_correo_electronico,
                ds_pagina_web,
                ds_telefono,
                cl_tipo_proveedor,
                cl_tipo_persona,
                cl_condicion_pago,
                nm_dias_pago,
                ic_responsable_iva,
                ic_aplica_retencion,
                ic_aplica_IVA,
                ic_precio_con_iva,
                ic_aplica_ICA,
                ds_contacto,
                nm_cuenta_puc,
                ic_registro_activo
            ) VALUES (
                v_ad_proveedor,
                p_cl_tipo_identificacion,
                p_ds_identificacion,
                p_nm_digito_verificacion,
                p_ds_razon_social,
                p_ds_nombre_comercial,
                p_ds_direccion,
                p_ds_ciudad,
                p_ds_correo_electronico,
                p_ds_pagina_web,
                p_ds_telefono,
                p_cl_tipo_proveedor,
                p_cl_tipo_persona,
                p_cl_condicion_pago,
                p_nm_dias_pago,
                p_ic_responsable_iva,
                p_ic_aplica_retencion,
                p_ic_aplica_IVA,
                p_ic_precio_con_iva,
                p_ic_aplica_ICA,
                p_ds_contacto,
                p_nm_cuenta_puc,
                'Y'
            );

            COMMIT;
            SET p_mensaje = 'Proveedor creado correctamente';

        WHEN 'U' THEN
            UPDATE proveedor
            SET ds_razon_social        = p_ds_razon_social,
                ds_nombre_comercial   = p_ds_nombre_comercial,
                ds_direccion           = p_ds_direccion,
                ds_ciudad              = p_ds_ciudad,
                ds_correo_electronico  = p_ds_correo_electronico,
                ds_pagina_web          = p_ds_pagina_web,
                ds_telefono            = p_ds_telefono,
                cl_tipo_proveedor      = p_cl_tipo_proveedor,
                cl_condicion_pago      = p_cl_condicion_pago,
                nm_dias_pago           = p_nm_dias_pago,
                ic_responsable_iva     = p_ic_responsable_iva,
                ic_aplica_retencion    = p_ic_aplica_retencion,
                ic_aplica_IVA          = p_ic_aplica_IVA,
                ic_precio_con_iva      = p_ic_precio_con_iva,
                ic_aplica_ICA          = p_ic_aplica_ICA,
                ds_contacto            = p_ds_contacto,
                nm_cuenta_puc          = p_nm_cuenta_puc
            WHERE ad_proveedor = p_ad_proveedor;

            IF ROW_COUNT() = 0 THEN
                SET p_mensaje = 'ERROR: Proveedor no encontrado';
                ROLLBACK;
                LEAVE proc;
            END IF;

            COMMIT;
            SET p_mensaje = 'Proveedor actualizado correctamente';

        WHEN 'D' THEN
            UPDATE proveedor
            SET ic_registro_activo = 'N'
            WHERE ad_proveedor = p_ad_proveedor;

            COMMIT;
            SET p_mensaje = 'Proveedor inactivado';

        WHEN 'C' THEN
            SELECT * FROM proveedor
            WHERE ds_identificacion = p_ds_identificacion
              AND ic_registro_activo = 'Y';

            SET p_mensaje = 'Consulta realizada';

        WHEN 'V' THEN
            SET p_mensaje = IF(v_existente > 0,'Proveedor activo: SI','Proveedor activo: NO');
    END CASE;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_gestionar_rol` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
