CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_gestionar_rol`(
    IN p_accion CHAR(1), -- I,U,D,C,V
    IN p_ad_rol INT,
    IN p_ds_nombre VARCHAR(50),
    IN p_ds_descripcion VARCHAR(255),
    IN p_usuario_auditoria INT,
    IN p_ds_ip VARCHAR(45),
    OUT p_mensaje VARCHAR(255)
)
proc: BEGIN
    DECLARE v_existente INT DEFAULT 0;
    DECLARE v_ad_rol INT DEFAULT 0;
    DECLARE v_error TEXT;

    /* =========================
       MANEJO DE ERRORES
    ==========================*/
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1
        v_error = MESSAGE_TEXT;

        ROLLBACK;

        INSERT INTO log_errores (
            modulo,
            operacion,
            mensaje_error,
            datos_entrada
        )
        VALUES (
            'sp_gestionar_rol',
            p_accion,
            v_error,
            CONCAT(
                'ad_rol=', IFNULL(p_ad_rol,'NULL'), '; ',
                'nombre=', IFNULL(p_ds_nombre,'NULL')
            )
        );

        SET p_mensaje = CONCAT('ERROR: ', v_error);
    END;

    /* =========================
       VALIDAR ACCIÓN
    ==========================*/
    IF p_accion NOT IN ('I','U','D','C','V') THEN
        SET p_mensaje = 'ERROR: Acción no válida. Use I,U,D,C,V';
        LEAVE proc;
    END IF;

    /* =========================
       VALIDAR EXISTENCIA
    ==========================*/
    IF p_accion IN ('I','V') THEN
        SELECT COUNT(*)
        INTO v_existente
        FROM roles
        WHERE ds_nombre = p_ds_nombre
          AND ic_activo = 'Y';
    END IF;

    /* =========================
       TRANSACCIÓN
    ==========================*/
    IF p_accion IN ('I','U','D') THEN
        START TRANSACTION;
    END IF;

    /* =========================
       LÓGICA PRINCIPAL
    ==========================*/
    CASE p_accion
        /* =====================
           INSERTAR
        ======================*/
        WHEN 'I' THEN
            IF v_existente > 0 THEN
                SET p_mensaje = 'ERROR: Ya existe un rol activo con ese nombre';
                ROLLBACK;
                LEAVE proc;
            END IF;

            SET v_ad_rol = fn_actualiza_secuencias('seq_rol');

            INSERT INTO roles (
                ad_rol,
                ds_nombre,
                ds_descripcion,
                ic_activo
            )
            VALUES (
                v_ad_rol,
                p_ds_nombre,
                p_ds_descripcion,
                'Y'
            );

            CALL sp_registrar_auditoria(
                p_usuario_auditoria,
                'SEGURIDAD',
                'CREAR',
                'roles',
                v_ad_rol,
                CONCAT('Rol registrado: ', p_ds_nombre),
                p_ds_ip
            );
            COMMIT;

            SET p_mensaje = CONCAT('Rol registrado correctamente. ID: ', v_ad_rol);

        /* =====================
           ACTUALIZAR
        ======================*/
        WHEN 'U' THEN
            IF p_ad_rol IS NULL THEN
                SET p_mensaje = 'ERROR: Debe indicar el ID del rol';
                ROLLBACK;
                LEAVE proc;
            END IF;

            UPDATE roles
            SET ds_nombre = p_ds_nombre,
                ds_descripcion = p_ds_descripcion
            WHERE ad_rol = p_ad_rol;

            IF ROW_COUNT() = 0 THEN
                SET p_mensaje = 'ERROR: Rol no encontrado o sin cambios';
                ROLLBACK;
                LEAVE proc;
            END IF;

            CALL sp_registrar_auditoria(
                p_usuario_auditoria,
                'SEGURIDAD',
                'ACTUALIZAR',
                'roles',
                p_ad_rol,
                CONCAT('Rol actualizado: ', p_ds_nombre),
                p_ds_ip
            );
            COMMIT;

            SET p_mensaje = 'Rol actualizado correctamente';

        /* =====================
           DESACTIVAR
        ======================*/
        WHEN 'D' THEN
            IF p_ad_rol IS NULL THEN
                SET p_mensaje = 'ERROR: Debe indicar el ID del rol';
                ROLLBACK;
                LEAVE proc;
            END IF;

            UPDATE roles
            SET ic_activo = 'N'
            WHERE ad_rol = p_ad_rol;

            IF ROW_COUNT() = 0 THEN
                SET p_mensaje = 'ERROR: Rol no encontrado';
                ROLLBACK;
                LEAVE proc;
            END IF;

            CALL sp_registrar_auditoria(
                p_usuario_auditoria,
                'SEGURIDAD',
                'DESACTIVAR',
                'roles',
                p_ad_rol,
                CONCAT('Rol desactivado ID ', p_ad_rol),
                p_ds_ip
            );
            
            COMMIT;

            SET p_mensaje = 'Rol desactivado correctamente';

        /* =====================
           CONSULTAR
        ======================*/
        WHEN 'C' THEN
            IF p_ad_rol IS NULL THEN
                SELECT *
                FROM roles
                WHERE ic_activo = 'Y'
                ORDER BY ds_nombre;
            ELSE
                SELECT *
                FROM roles
                WHERE ad_rol = p_ad_rol;
            END IF;

            SET p_mensaje = 'Consulta realizada correctamente';

        /* =====================
           VALIDAR EXISTENCIA
        ======================*/
        WHEN 'V' THEN
            IF v_existente > 0 THEN
                SET p_mensaje = 'Rol existe: SI';
            ELSE
                SET p_mensaje = 'Rol existe: NO';
            END IF;
    END CASE;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
