CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_gestionar_rol_permiso`(
    IN p_accion CHAR(1), -- I,D,C,V
    IN p_fk_rol_ad_rol INT,
    IN p_fk_permiso_ad_permiso INT,
    OUT p_mensaje VARCHAR(255)
)
proc: BEGIN
    DECLARE v_existente INT DEFAULT 0;
    DECLARE v_error TEXT;

    /* =========================
       MANEJO DE ERRORES
    ==========================*/
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1
        v_error = MESSAGE_TEXT;
        ROLLBACK;

        INSERT INTO log_errores (
            modulo,
            operacion,
            mensaje_error,
            datos_entrada
        )
        VALUES (
            'sp_gestionar_rol_permiso',
            p_accion,
            v_error,
            CONCAT(
                'rol=', IFNULL(p_fk_rol_ad_rol,'NULL'), '; ',
                'permiso=', IFNULL(p_fk_permiso_ad_permiso,'NULL')
            )
        );

        SET p_mensaje = CONCAT('ERROR: ', v_error);
    END;

    /* =========================
       VALIDAR ACCIÓN
    ==========================*/
    IF p_accion NOT IN ('I','D','C','V') THEN
        SET p_mensaje = 'ERROR: Acción no válida. Use I,D,C,V';
        LEAVE proc;
    END IF;

    /* =========================
       VALIDAR EXISTENCIA
    ==========================*/
    IF p_accion IN ('I','D','V') THEN
        SELECT COUNT(*)
        INTO v_existente
        FROM rol_permiso
        WHERE fk_rol_ad_rol = p_fk_rol_ad_rol
          AND fk_permiso_ad_permiso = p_fk_permiso_ad_permiso;
    END IF;

    /* =========================
       TRANSACCIÓN
    ==========================*/
    IF p_accion IN ('I','D') THEN
        START TRANSACTION;
    END IF;

    /* =========================
       LÓGICA PRINCIPAL
    ==========================*/
    CASE p_accion
        /* =====================
           ASIGNAR PERMISO
        ======================*/
        WHEN 'I' THEN
            IF v_existente > 0 THEN
                SET p_mensaje = 'ERROR: El permiso ya está asignado al rol';
                ROLLBACK;
                LEAVE proc;
            END IF;

            INSERT INTO rol_permiso (
                fk_rol_ad_rol,
                fk_permiso_ad_permiso
            )
            VALUES (
                p_fk_rol_ad_rol,
                p_fk_permiso_ad_permiso
            );

            COMMIT;

            SET p_mensaje = 'Permiso asignado correctamente al rol';

        /* =====================
           REMOVER PERMISO
        ======================*/
        WHEN 'D' THEN
            IF v_existente = 0 THEN
                SET p_mensaje = 'ERROR: El rol no tiene asignado ese permiso';
                ROLLBACK;
                LEAVE proc;
            END IF;

            DELETE FROM rol_permiso
            WHERE fk_rol_ad_rol = p_fk_rol_ad_rol
              AND fk_permiso_ad_permiso = p_fk_permiso_ad_permiso;

            COMMIT;

            SET p_mensaje = 'Permiso removido correctamente del rol';

        /* =====================
           CONSULTAR
        ======================*/
        WHEN 'C' THEN
            IF p_fk_rol_ad_rol IS NULL THEN
                SELECT
                    rp.fk_rol_ad_rol,
                    r.ds_nombre AS ds_rol,
                    rp.fk_permiso_ad_permiso,
                    p.ds_codigo,
                    p.ds_nombre_permiso,
                    p.ds_modulo
                FROM rol_permiso rp
                INNER JOIN roles r
                    ON r.ad_rol = rp.fk_rol_ad_rol
                INNER JOIN permiso_acceso p
                    ON p.ad_permiso_acceso = rp.fk_permiso_ad_permiso
                WHERE p.ic_registro_activo = 'Y'
                  AND r.ic_activo = 'Y'
                ORDER BY
                    r.ds_nombre,
                    p.ds_modulo,
                    p.ds_nombre_permiso;
            ELSE
                SELECT
                    rp.fk_rol_ad_rol,
                    r.ds_nombre AS ds_rol,
                    rp.fk_permiso_ad_permiso,
                    p.ds_codigo,
                    p.ds_nombre_permiso,
                    p.ds_modulo
                FROM rol_permiso rp
                INNER JOIN roles r
                    ON r.ad_rol = rp.fk_rol_ad_rol
                INNER JOIN permiso_acceso p
                    ON p.ad_permiso_acceso = rp.fk_permiso_ad_permiso
                WHERE rp.fk_rol_ad_rol = p_fk_rol_ad_rol
                  AND p.ic_registro_activo = 'Y'
                  AND r.ic_activo = 'Y'
                ORDER BY
                    p.ds_modulo,
                    p.ds_nombre_permiso;
            END IF;

            SET p_mensaje = 'Consulta realizada correctamente';

        /* =====================
           VALIDAR EXISTENCIA
        ======================*/
        WHEN 'V' THEN
            IF v_existente > 0 THEN
                SET p_mensaje = 'Asignación existe: SI';
            ELSE
                SET p_mensaje = 'Asignación existe: NO';
            END IF;
    END CASE;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
