CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_gestionar_subgrupo_producto`(
    IN p_accion CHAR(1), -- I, U, D, C, V
    IN p_ad_subgrupo_producto INT,
    IN p_fk_grupo_ad_grupo_producto INT,
    IN p_ds_nombre VARCHAR(45),
    IN p_cl_metodo_almacenamiento VARCHAR(2),
    OUT p_mensaje VARCHAR(255)
)
proc: BEGIN
    DECLARE v_existente INT DEFAULT 0;
    DECLARE v_id_subgrupo INT;
    DECLARE v_error TEXT;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 v_error = MESSAGE_TEXT;

        ROLLBACK;

        INSERT INTO log_errores(
            modulo,
            operacion,
            mensaje_error,
            datos_entrada
        )
        VALUES(
            'sp_gestionar_subgrupo_producto',
            p_accion,
            v_error,
            CONCAT(
                'subgrupo=',IFNULL(p_ad_subgrupo_producto,'NULL'),
                '; grupo=',IFNULL(p_fk_grupo_ad_grupo_producto,'NULL'),
                '; nombre=',IFNULL(p_ds_nombre,'NULL')
            )
        );

        SET p_mensaje = CONCAT('ERROR: ', v_error);
    END;

    /* ================= VALIDACIONES ================= */

    IF p_accion NOT IN ('I','U','D','C','V') THEN
        SET p_mensaje = 'ERROR: Acción inválida';
        LEAVE proc;
    END IF;

    IF p_accion IN ('I','U') THEN

        IF p_ds_nombre IS NULL OR p_ds_nombre = '' THEN
            SET p_mensaje = 'ERROR: Nombre del subgrupo obligatorio';
            LEAVE proc;
        END IF;

    END IF;

    /* ================= VALIDAR EXISTENCIA ================= */

    IF p_accion IN ('U','D','V') THEN

        SELECT COUNT(*)
        INTO v_existente
        FROM subgrupo_producto
        WHERE ad_subgrupo_producto = p_ad_subgrupo_producto;

    END IF;

    /* ================= TRANSACCION ================= */

    IF p_accion IN ('I','U','D') THEN
        START TRANSACTION;
    END IF;

    /* ================= ACCIONES ================= */

    CASE p_accion

    /* ================= INSERTAR ================= */

    WHEN 'I' THEN

        /* evitar duplicados */

        SELECT COUNT(*)
        INTO v_existente
        FROM subgrupo_producto
        WHERE ds_nombre = p_ds_nombre
        AND fk_grupo_ad_grupo_producto = p_fk_grupo_ad_grupo_producto;

        IF v_existente > 0 THEN
            SET p_mensaje = 'ERROR: el subgrupo ya existe para este grupo';
            ROLLBACK;
            LEAVE proc;
        END IF;

        SET v_id_subgrupo =
        fn_actualiza_secuencias('seq_subgrupo_producto');

        INSERT INTO subgrupo_producto(
            ad_subgrupo_producto,
            fk_grupo_ad_grupo_producto,
            ds_nombre,
            cl_metodo_almacenamiento
        )
        VALUES(
            v_id_subgrupo,
            p_fk_grupo_ad_grupo_producto,
            p_ds_nombre,
            p_cl_metodo_almacenamiento
        );

        COMMIT;

        SET p_mensaje = 'Subgrupo creado correctamente';

    /* ================= ACTUALIZAR ================= */

    WHEN 'U' THEN

        IF v_existente = 0 THEN
            SET p_mensaje = 'ERROR: subgrupo no existe';
            ROLLBACK;
            LEAVE proc;
        END IF;

        UPDATE subgrupo_producto
        SET
            fk_grupo_ad_grupo_producto = p_fk_grupo_ad_grupo_producto,
            ds_nombre = p_ds_nombre,
            cl_metodo_almacenamiento = p_cl_metodo_almacenamiento
        WHERE ad_subgrupo_producto = p_ad_subgrupo_producto;

        COMMIT;

        SET p_mensaje = 'Subgrupo actualizado correctamente';

    /* ================= ELIMINAR ================= */

    WHEN 'D' THEN

        IF v_existente = 0 THEN
            SET p_mensaje = 'ERROR: subgrupo no existe';
            ROLLBACK;
            LEAVE proc;
        END IF;

        DELETE FROM subgrupo_producto
        WHERE ad_subgrupo_producto = p_ad_subgrupo_producto;

        COMMIT;

        SET p_mensaje = 'Subgrupo eliminado correctamente';

    /* ================= CONSULTAR ================= */

    WHEN 'C' THEN

        SELECT
            s.ad_subgrupo_producto,
            s.ds_nombre,
            s.cl_metodo_almacenamiento,
            g.ds_nombre_grupo
        FROM subgrupo_producto s
        JOIN grupo_producto g
        ON g.ad_grupo_producto = s.fk_grupo_ad_grupo_producto;

        SET p_mensaje = 'Consulta realizada correctamente';

    /* ================= VALIDAR ================= */

    WHEN 'V' THEN

        IF v_existente > 0 THEN
            SET p_mensaje = 'Subgrupo existe';
        ELSE
            SET p_mensaje = 'Subgrupo NO existe';
        END IF;

    END CASE;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
