DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_gestionar_usuario`(
    IN p_accion CHAR(1), -- I,U,D,C,V
    IN p_ad_usuario INT,
    IN p_ds_usuario VARCHAR(45),
    IN p_ds_password VARCHAR(255),
    IN p_ds_nombre VARCHAR(100),
    IN p_ds_email VARCHAR(100),
    IN p_fk_sucursal_ad_sucursal INT,
    IN p_usuario_auditoria INT,
    IN p_ds_ip VARCHAR(45),
    OUT p_mensaje VARCHAR(255)
)
proc: BEGIN
    DECLARE v_existente INT DEFAULT 0;
    DECLARE v_ad_usuario INT DEFAULT 0;
    DECLARE v_error TEXT;

    /* =========================
       MANEJO DE ERRORES
    ==========================*/
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 
        v_error = MESSAGE_TEXT;

        ROLLBACK;

        INSERT INTO log_errores (
            modulo,
            operacion,
            mensaje_error,
            datos_entrada
        )
        VALUES (
            'sp_gestionar_usuario',
            p_accion,
            v_error,
            CONCAT(
                'ad_usuario=', IFNULL(p_ad_usuario,'NULL'), '; ',
                'usuario=', IFNULL(p_ds_usuario,'NULL'), '; ',
                'nombre=', IFNULL(p_ds_nombre,'NULL')
            )
        );

        SET p_mensaje = CONCAT('ERROR: ', v_error);
    END;

    /* =========================
       VALIDAR ACCIÓN
    ==========================*/
    IF p_accion NOT IN ('I','U','D','C','V') THEN
        SET p_mensaje = 'ERROR: Acción no válida. Use I,U,D,C,V';
        LEAVE proc;
    END IF;

    /* =========================
       VALIDAR EXISTENCIA USUARIO
    ==========================*/
    IF p_accion IN ('I','V') THEN
        SELECT COUNT(*)
        INTO v_existente
        FROM usuarios
        WHERE ds_usuario = p_ds_usuario;
    END IF;

    /* =========================
       TRANSACCIÓN
    ==========================*/
    IF p_accion IN ('I','U','D') THEN
        START TRANSACTION;
    END IF;

    /* =========================
       LÓGICA PRINCIPAL
    ==========================*/
    CASE p_accion
        /* =====================
           INSERTAR
        ======================*/
        WHEN 'I' THEN
            IF v_existente > 0 THEN
                SET p_mensaje = 'ERROR: El usuario ya existe';
                ROLLBACK;
                LEAVE proc;
            END IF;

            SET v_ad_usuario = fn_actualiza_secuencias('seq_usuario');

            INSERT INTO usuarios (
                ad_usuario,
                ds_usuario,
                ds_password,
                ds_nombre,
                ds_email,
                fk_sucursal_ad_sucursal,
                ic_activo,
                dt_creacion
            )
            VALUES (
                v_ad_usuario,
                p_ds_usuario,
                p_ds_password,
                p_ds_nombre,
                p_ds_email,
                p_fk_sucursal_ad_sucursal,
                'Y',
                NOW()
            );

            CALL sp_registrar_auditoria(
                p_usuario_auditoria,
                'SEGURIDAD',
                'CREAR',
                'usuarios',
                v_ad_usuario,
                CONCAT('Usuario registrado: ', p_ds_usuario),
                p_ds_ip
            );
            COMMIT;

            SET p_mensaje = CONCAT('Usuario registrado correctamente. ID: ', v_ad_usuario);

        /* =====================
           ACTUALIZAR
        ======================*/
        WHEN 'U' THEN
            IF p_ad_usuario IS NULL THEN
                SET p_mensaje = 'ERROR: Debe indicar el usuario';
                ROLLBACK;
                LEAVE proc;
            END IF;

            UPDATE usuarios
            SET ds_nombre = p_ds_nombre,
                ds_email = p_ds_email,
                fk_sucursal_ad_sucursal =
                p_fk_sucursal_ad_sucursal
            WHERE ad_usuario = p_ad_usuario;

            IF ROW_COUNT() = 0 THEN
                SET p_mensaje = 'ERROR: Usuario no encontrado o sin cambios';
                ROLLBACK;
                LEAVE proc;
            END IF;

            CALL sp_registrar_auditoria(
                p_usuario_auditoria,
                'SEGURIDAD',
                'ACTUALIZAR',
                'usuarios',
                p_ad_usuario,
                CONCAT('Usuario actualizado: ', p_ds_usuario),
                p_ds_ip
            );
            COMMIT;

            SET p_mensaje = 'Usuario actualizado correctamente';

        /* =====================
           DESACTIVAR
        ======================*/
        WHEN 'D' THEN
            IF p_ad_usuario IS NULL THEN
                SET p_mensaje = 'ERROR: Debe indicar el usuario';
                ROLLBACK;
                LEAVE proc;
            END IF;

            UPDATE usuarios
            SET ic_activo = 'N'
            WHERE ad_usuario = p_ad_usuario;

            IF ROW_COUNT() = 0 THEN
                SET p_mensaje = 'ERROR: Usuario no encontrado';
                ROLLBACK;
                LEAVE proc;
            END IF;

            CALL sp_registrar_auditoria(
                p_usuario_auditoria,
                'SEGURIDAD',
                'DESACTIVAR',
                'usuarios',
                p_ad_usuario,
                CONCAT('Usuario desactivado ID ', p_ad_usuario),
                p_ds_ip
            );

            COMMIT;

            SET p_mensaje = 'Usuario desactivado correctamente';

        /* =====================
           CONSULTAR
        ======================*/
        WHEN 'C' THEN
            IF p_ad_usuario IS NULL THEN
                SELECT *
                FROM usuarios
                WHERE ic_activo = 'Y'
                ORDER BY ds_nombre;
            ELSE
                SELECT *
                FROM usuarios
                WHERE ad_usuario = p_ad_usuario;
            END IF;

            SET p_mensaje = 'Consulta realizada correctamente';

        /* =====================
           VALIDAR EXISTENCIA
        ======================*/
        WHEN 'V' THEN
            IF v_existente > 0 THEN
                SET p_mensaje = 'Usuario existe: SI';
            ELSE
                SET p_mensaje = 'Usuario existe: NO';
            END IF;
    END CASE;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_gestionar_usuario_rol` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
