CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_gestionar_usuario_rol`(
    IN p_accion CHAR(1), -- I,D,C,V
    IN p_fk_usuario_ad_usuario INT,
    IN p_fk_rol_ad_rol INT,
    OUT p_mensaje VARCHAR(255)
)
proc: BEGIN
    DECLARE v_existente INT DEFAULT 0;
    DECLARE v_error TEXT;

    /* =========================
       MANEJO DE ERRORES
    ==========================*/
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1
        v_error = MESSAGE_TEXT;
        ROLLBACK;

        INSERT INTO log_errores (
            modulo,
            operacion,
            mensaje_error,
            datos_entrada
        )
        VALUES (
            'sp_gestionar_usuario_rol',
            p_accion,
            v_error,
            CONCAT(
                'usuario=', IFNULL(p_fk_usuario_ad_usuario,'NULL'), '; ',
                'rol=', IFNULL(p_fk_rol_ad_rol,'NULL')
            )
        );

        SET p_mensaje = CONCAT('ERROR: ', v_error);
    END;

    /* =========================
       VALIDAR ACCIÓN
    ==========================*/
    IF p_accion NOT IN ('I','D','C','V') THEN
        SET p_mensaje = 'ERROR: Acción no válida. Use I,D,C,V';
        LEAVE proc;
    END IF;

    /* =========================
       VALIDAR EXISTENCIA
    ==========================*/
    IF p_accion IN ('I','V','D') THEN
        SELECT COUNT(*)
        INTO v_existente
        FROM usuario_rol
        WHERE fk_usuario_ad_usuario = p_fk_usuario_ad_usuario
          AND fk_rol_ad_rol = p_fk_rol_ad_rol;
    END IF;

    /* =========================
       TRANSACCIÓN
    ==========================*/
    IF p_accion IN ('I','D') THEN
        START TRANSACTION;
    END IF;

    /* =========================
       LÓGICA PRINCIPAL
    ==========================*/
    CASE p_accion
        /* =====================
           ASIGNAR ROL
        ======================*/
        WHEN 'I' THEN
            IF v_existente > 0 THEN
                SET p_mensaje = 'ERROR: El rol ya está asignado al usuario';
                ROLLBACK;
                LEAVE proc;
            END IF;

            INSERT INTO usuario_rol (
                fk_usuario_ad_usuario,
                fk_rol_ad_rol
            )
            VALUES (
                p_fk_usuario_ad_usuario,
                p_fk_rol_ad_rol
            );

            COMMIT;

            SET p_mensaje = 'Rol asignado correctamente al usuario';

        /* =====================
           REMOVER ROL
        ======================*/
        WHEN 'D' THEN
            IF v_existente = 0 THEN
                SET p_mensaje = 'ERROR: El usuario no tiene asignado ese rol';
                ROLLBACK;
                LEAVE proc;
            END IF;

            DELETE FROM usuario_rol
            WHERE fk_usuario_ad_usuario = p_fk_usuario_ad_usuario
              AND fk_rol_ad_rol = p_fk_rol_ad_rol;

            COMMIT;

            SET p_mensaje = 'Rol removido correctamente del usuario';

        /* =====================
           CONSULTAR
        ======================*/
        WHEN 'C' THEN
            IF p_fk_usuario_ad_usuario IS NULL THEN
                SELECT
                    ur.fk_usuario_ad_usuario,
                    u.ds_usuario,
                    u.ds_nombre,
                    ur.fk_rol_ad_rol,
                    r.ds_nombre AS ds_rol
                FROM usuario_rol ur
                INNER JOIN usuarios u
                    ON u.ad_usuario = ur.fk_usuario_ad_usuario
                INNER JOIN roles r
                    ON r.ad_rol = ur.fk_rol_ad_rol
                ORDER BY
                    u.ds_nombre,
                    r.ds_nombre;
            ELSE
                SELECT
                    ur.fk_usuario_ad_usuario,
                    u.ds_usuario,
                    u.ds_nombre,
                    ur.fk_rol_ad_rol,
                    r.ds_nombre AS ds_rol
                FROM usuario_rol ur
                INNER JOIN usuarios u
                    ON u.ad_usuario = ur.fk_usuario_ad_usuario
                INNER JOIN roles r
                    ON r.ad_rol = ur.fk_rol_ad_rol
                WHERE ur.fk_usuario_ad_usuario = p_fk_usuario_ad_usuario
                ORDER BY r.ds_nombre;
            END IF;

            SET p_mensaje = 'Consulta realizada correctamente';

        /* =====================
           VALIDAR EXISTENCIA
        ======================*/
        WHEN 'V' THEN
            IF v_existente > 0 THEN
                SET p_mensaje = 'Asignación existe: SI';
            ELSE
                SET p_mensaje = 'Asignación existe: NO';
            END IF;
    END CASE;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_registrar_auditoria` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
