CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_registrar_auditoria`(
    IN p_fk_usuario_ad_usuario INT,
    IN p_ds_modulo VARCHAR(50),
    IN p_ds_accion VARCHAR(50),
    IN p_ds_tabla VARCHAR(50),
    IN p_fk_registro INT,
    IN p_ds_descripcion TEXT,
    IN p_ds_ip VARCHAR(45)
)
BEGIN
    INSERT INTO auditoria (
        ad_auditoria,
        fk_usuario_ad_usuario,
        ds_modulo,
        ds_accion,
        ds_tabla,
        fk_registro,
        ds_descripcion,
        dt_fecha,
        ds_ip
    )
    VALUES (
        fn_actualiza_secuencias('seq_auditoria'),
        p_fk_usuario_ad_usuario,
        p_ds_modulo,
        p_ds_accion,
        p_ds_tabla,
        p_fk_registro,
        p_ds_descripcion,
        NOW(),
        p_ds_ip
    );
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_registrar_factura_compra_desde_orden` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
