/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_registrar_factura_compra_desde_orden`(
    IN p_fk_ordencom_ad_orden INT,
    OUT p_ad_factura INT,
    OUT p_mensaje VARCHAR(255)
)
proc: BEGIN
    DECLARE v_ad_factura INT;
    DECLARE v_existe INT DEFAULT 0;
    DECLARE v_error TEXT;
    DECLARE v_total_detalle DECIMAL(12,4) DEFAULT 0;

    /* VARIABLES CURSOR */
    DECLARE v_producto INT;
    DECLARE v_prodprov INT;
    DECLARE v_cantidad DECIMAL(12,4);
    DECLARE v_precio DECIMAL(12,4);
    DECLARE done INT DEFAULT FALSE;

    /* ========================================= */
    /* CURSOR DETALLE ORDEN */
    /* ========================================= */
    DECLARE cur_detalle CURSOR FOR
        SELECT p.fk_productos_ad_producto,
            d.fk_prodprov_ad_produprov,
            d.vl_cantidad,
            d.vl_precio_unitario
        FROM detalles_orden_compra d, productos_proveedor p
        WHERE d.fk_ordencom_ad_orden = p_fk_ordencom_ad_orden
          AND d.fk_prodprov_ad_produprov = p.ad_productos_proveedor;

    DECLARE CONTINUE HANDLER FOR NOT FOUND
        SET done = TRUE;

    /* ========================================= */
    /* MANEJO ERRORES */
    /* ========================================= */
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1
            v_error = MESSAGE_TEXT;
        ROLLBACK;

        SET p_ad_factura = NULL;
        SET p_mensaje = CONCAT('ERROR: ', v_error);
    END;

    /* ========================================= */
    /* VALIDAR ORDEN */
    /* ========================================= */

    SELECT COUNT(*)
    INTO v_existe
    FROM ordenes_compra
    WHERE ad_orden = p_fk_ordencom_ad_orden
      AND ds_estado = 'CO';

    IF v_existe > 0 THEN
        SET p_mensaje = 'ERROR: Orden no válida o no completada';
        LEAVE proc;
    END IF;

    START TRANSACTION;

    /* ========================================= */
    /* CREAR FACTURA CABECERA */
    /* ========================================= */

    SET v_ad_factura = fn_actualiza_secuencias('seq_factura_compra');

    INSERT INTO factura_compra (
        ad_factura,
        fk_provee_ad_proveedor,
        fk_sucursal_ad_sucursal,
        fk_ordencom_ad_orden,
        ds_numero_factura,
        dt_fecha_factura,
        vl_facturado,
        vl_descuento,
        vl_impuestos,
        vl_retencion,
        vl_total,
        vl_pagado,
        vl_saldo,
        ds_estado_factura,
        ds_estado_pago,
        ds_observaciones,
        ic_cuenta_cobro
    )
    SELECT
        v_ad_factura,
        o.fk_provee_ad_proveedor,
        o.fk_sucursal_ad_sucursal,
        o.ad_orden,
        CONCAT('BORRADOR-', v_ad_factura),
        CURDATE(),
        0,
        0,
        0,
        0,
        0,
        0,
        0,
        'RE',
        'PE',
        CONCAT('Factura generada desde orden ', o.ad_orden),
        'N'
    FROM ordenes_compra o
    WHERE o.ad_orden = p_fk_ordencom_ad_orden;

    /* ========================================= */
    /* RECORRER DETALLE */
    /* ========================================= */

    OPEN cur_detalle;

    read_loop: LOOP

        FETCH cur_detalle INTO
            v_producto,
            v_prodprov,
            v_cantidad,
            v_precio;

        IF done THEN
            LEAVE read_loop;
        END IF;

        /* ===================================== */
        /* INSERT DETALLE FACTURA */
        /* ===================================== */

        CALL sp_gestionar_detalle_factura_compra(
            v_ad_factura,
            v_producto,
            v_prodprov,
            v_cantidad,
            v_precio,
            @p_id_detalle,
            @p_msg
        );

    END LOOP;

    CLOSE cur_detalle;

    /* ========================================= */
    /* CALCULAR TOTAL FACTURA */
    /* ========================================= */
    SELECT SUM(vl_subtotal)
    INTO v_total_detalle
    FROM detalle_factura_compra
    WHERE fk_factura_ad_factura = v_ad_factura;

    UPDATE factura_compra
       SET vl_facturado = v_total_detalle,
           vl_total = v_total_detalle,
           vl_saldo = v_total_detalle
    WHERE ad_factura = v_ad_factura;

    /* ========================================= */
    /* ACTUALIZAR ORDEN */
    /* ========================================= */
    UPDATE ordenes_compra
       SET ds_estado = 'FA'
    WHERE ad_orden = p_fk_ordencom_ad_orden;

    COMMIT;

    SET p_ad_factura = v_ad_factura;

    SET p_mensaje = CONCAT('Factura generada correctamente desde orden. ID: ', v_ad_factura);

END ;;
DELIMITER ;
