DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_registrar_tipo_impuesto`(
    IN p_accion CHAR(1),
    IN p_ad_tipo_impuesto INT,
    IN p_cl_codigo_impuesto VARCHAR(2),
    IN p_ds_nombre VARCHAR(100),
    IN p_pr_porcentaje DECIMAL(5,2),
    IN p_cl_tipo_impuesto VARCHAR(2),
    OUT p_id_tipo_impuesto INT,
    OUT p_mensaje VARCHAR(255)
)
proc: BEGIN
    DECLARE v_error TEXT;

    /* MANEJO DE ERRORES */
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 v_error = MESSAGE_TEXT;

        SET p_id_tipo_impuesto = NULL;

        SET p_mensaje = CONCAT(
            'ERROR: ',
            v_error
        );
    END;

    /* ========================================= */
    /* INSERTAR */
    /* ========================================= */
    IF p_accion = 'I' THEN

        /* VALIDACIONES */
        IF p_cl_codigo_impuesto IS NULL
           OR TRIM(p_cl_codigo_impuesto) = ''
           OR p_ds_nombre IS NULL
           OR TRIM(p_ds_nombre) = ''
           OR p_pr_porcentaje < 0
           OR p_cl_tipo_impuesto IS NULL
           OR TRIM(p_cl_tipo_impuesto) = ''
        THEN
            SET p_mensaje = 'ERROR: Datos inválidos';
            LEAVE proc;
        END IF;

        /* VALIDAR DUPLICADO */
        IF EXISTS (
            SELECT 1
              FROM tipo_impuesto
             WHERE cl_codigo_impuesto = p_cl_codigo_impuesto
        ) THEN
            SET p_mensaje = 'ERROR: El código de impuesto ya existe';
            LEAVE proc;
        END IF;

        /* GENERAR ID */
        SET p_id_tipo_impuesto =
            fn_actualiza_secuencias('seq_tipo_impuesto');

        /* INSERT */
        INSERT INTO tipo_impuesto (
            ad_tipo_impuesto,
            cl_codigo_impuesto,
            ds_nombre,
            pr_porcentaje,
            cl_tipo_impuesto,
            ic_activo
        )
        VALUES (
            p_id_tipo_impuesto,
            p_cl_codigo_impuesto,
            p_ds_nombre,
            p_pr_porcentaje,
            p_cl_tipo_impuesto,
            'Y'
        );

        SET p_mensaje =
            CONCAT(
                'Tipo impuesto registrado correctamente. ID: ',
                p_id_tipo_impuesto
            );
    END IF;

    /* ========================================= */
    /* ACTUALIZAR */
    /* ========================================= */
    IF p_accion = 'U' THEN

        IF NOT EXISTS (
            SELECT 1
              FROM tipo_impuesto
             WHERE ad_tipo_impuesto = p_ad_tipo_impuesto
        ) THEN
            SET p_mensaje =
                'ERROR: El tipo impuesto no existe';
            LEAVE proc;
        END IF;

        UPDATE tipo_impuesto
           SET cl_codigo_impuesto = p_cl_codigo_impuesto,
               ds_nombre = p_ds_nombre,
               pr_porcentaje = p_pr_porcentaje,
               cl_tipo_impuesto = p_cl_tipo_impuesto
         WHERE ad_tipo_impuesto = p_ad_tipo_impuesto;

        SET p_id_tipo_impuesto = p_ad_tipo_impuesto;
        SET p_mensaje = 'Tipo impuesto actualizado correctamente';
    END IF;

    /* ========================================= */
    /* ELIMINAR LOGICO */
    /* ========================================= */
    IF p_accion = 'D' THEN

        IF NOT EXISTS (
            SELECT 1
              FROM tipo_impuesto
             WHERE ad_tipo_impuesto = p_ad_tipo_impuesto
        ) THEN
            SET p_mensaje = 'ERROR: El tipo impuesto no existe';
            LEAVE proc;
        END IF;

        UPDATE tipo_impuesto
           SET ic_activo = 'N'
         WHERE ad_tipo_impuesto = p_ad_tipo_impuesto;

        SET p_id_tipo_impuesto = p_ad_tipo_impuesto;
        SET p_mensaje = 'Tipo impuesto desactivado correctamente';
    END IF;

    /* ========================================= */
    /* CONSULTAR */
    /* ========================================= */
    IF p_accion = 'C' THEN

        SELECT
            ad_tipo_impuesto,
            cl_codigo_impuesto,
            ds_nombre,
            pr_porcentaje,
            cl_tipo_impuesto,
            ic_activo,
            dt_creacion
        FROM tipo_impuesto
        WHERE ad_tipo_impuesto = p_ad_tipo_impuesto;

        SET p_mensaje = 'Consulta realizada correctamente';
    END IF;
END ;;
DELIMITER ;
